    float GradeToZ( float grade )
    {
        // Same law as Unreal / terrain_caps: height_voxels = (grade - datum) * relief; meters = * voxel_edge
        return ( grade - g.gradeDatum ) * g.reliefVoxels * g.voxelEdgeM;
    }

