    // Stage 15 reaches through the Stage-12 differential-erosion kernel, whose
    // certified dual-surface acceleration caches are mutable. Sharing one
    // instance between terrain workers would race those maps. Each worker owns
    // an identical descriptor-linked kernel instead; results remain byte-stable
    // while the cache is private to the job lane that mutates it.
    CausalBareEarthGeography::Kernel* ThreadBareEarthKernel()
    {
        thread_local std::unique_ptr<CausalBareEarthGeography::Kernel> kernel;
        thread_local bool attempted=false;
        if(!attempted)
        {
            attempted=true;std::string reason;
            kernel=CausalBareEarthGeography::LoadKernel(
                "Data\\Worldgen\\causal_world_geology_kernel_floor.cwg",
                "Data\\Worldgen\\causal_world_geologic_exposure_floor.cwe",
                "Data\\Worldgen\\causal_world_differential_erosion_floor.cde",
                "Data\\Worldgen\\causal_world_granite_intrusion_floor.cgi",
                "Data\\Worldgen\\causal_world_contact_mineralization_floor.ccm",
                "Data\\Worldgen\\causal_world_fault_displacement_floor.cfd",
                "Data\\Worldgen\\causal_world_surface_breach_continuity_floor.cbc",
                "Data\\Worldgen\\causal_world_bare_earth_geography_floor.cbg",&reason);
        }
        return kernel.get();
    }

    CausalVisibleExposure::BlockSurfaceSamples SampleCompiledFluvialWorkerBlock(
        CausalBareEarthGeography::Kernel const& geography,
        CausalCompiledFluvialErosion::Kernel const& erosion,int bx,int by)
    {
        CausalVisibleExposure::BlockSurfaceSamples samples;samples.blockX=bx;samples.blockY=by;
        samples.vertices.reserve((size_t)CausalVisibleExposure::kBlockSampleSpan
            *CausalVisibleExposure::kBlockSampleSpan);
        int const baseX=bx*CausalVisibleExposure::kBlockCells-1;
        int const baseY=by*CausalVisibleExposure::kBlockCells-1;
        for(int y=0;y<CausalVisibleExposure::kBlockSampleSpan;++y)
        for(int x=0;x<CausalVisibleExposure::kBlockSampleSpan;++x)
        {
            double const wx=(baseX+x+.5)*CausalVisibleExposure::kDualStepM;
            double const wy=(baseY+y+.5)*CausalVisibleExposure::kDualStepM;
            double const stage15Z=geography.ReconstructedZ(wx,wy);
            samples.vertices.push_back({wx,wy,stage15Z
                -erosion.AuthorizedIncisionDepth(geography,wx,wy,stage15Z)});
        }
        return samples;
    }

    CausalVisibleExposure::BlockSurfaceSamples SampleCompiledSedimentWorkerBlock(
        CausalBareEarthGeography::Kernel const& geography,
        CausalCompiledSediment::Kernel const& sediment,int bx,int by)
    {
        CausalVisibleExposure::BlockSurfaceSamples samples;samples.blockX=bx;samples.blockY=by;
        samples.vertices.reserve((size_t)CausalVisibleExposure::kBlockSampleSpan
            *CausalVisibleExposure::kBlockSampleSpan);
        int const baseX=bx*CausalVisibleExposure::kBlockCells-1;
        int const baseY=by*CausalVisibleExposure::kBlockCells-1;
        for(int y=0;y<CausalVisibleExposure::kBlockSampleSpan;++y)
        for(int x=0;x<CausalVisibleExposure::kBlockSampleSpan;++x)
        {
            double const wx=(baseX+x+.5)*CausalVisibleExposure::kDualStepM;
            double const wy=(baseY+y+.5)*CausalVisibleExposure::kDualStepM;
            double const stage15Z=geography.ReconstructedZ(wx,wy);
            double const stage16bZ=stage15Z-sediment.Erosion().AuthorizedIncisionDepth(
                geography,wx,wy,stage15Z);
            samples.vertices.push_back({wx,wy,stage16bZ+sediment.DepositDepth(wx,wy)});
        }
        return samples;
    }

    CausalBareEarthGeography::Kernel const* ActiveBareEarthKernel(Stage0PlayView view)
    {
        if(UsesPresentWaterOccupancy(view)&&ActivePresentWaterKernel())
            return &ActivePresentWaterKernel()->Geography();
        if(IsCompiledSedimentView(view)&&g.compiledSedimentRuntime)
            return &g.compiledSedimentRuntime->Geography();
        if(IsCompiledFluvialErosionView(view)&&g.compiledFluvialRuntime)
            return &g.compiledFluvialRuntime->Geography();
        if(IsDryHydrologyView(view)&&g.dryHydrologyRuntime)
            return &g.dryHydrologyRuntime->Geography();
        if(IsBareEarthGeographyView(view))return g.bareEarthRuntime.get();
        return nullptr;
    }

    bool SampleResidentCausalPackageSurface(double x,double y,float& outZ)
    {
        double const shiftedX=x+0.5*CausalVisibleExposure::kDualStepM;
        double const shiftedY=y+0.5*CausalVisibleExposure::kDualStepM;
        int const bx=(int)std::floor(shiftedX/CausalVisibleExposure::kBlockSizeM);
        int const by=(int)std::floor(shiftedY/CausalVisibleExposure::kBlockSizeM);
        auto const block=g.stage8TerrainBlocks.find(CellKey(bx,by));
        if(block==g.stage8TerrainBlocks.end()||!block->second.collisionSurface)
        {return false;}
        double resolved=0.0;
        if(!CausalVisibleExposure::ReconstructedZ(
            *block->second.collisionSurface,x,y,resolved))return false;
        outZ=(float)resolved;
        return std::isfinite(outZ);
    }

    bool SampleCausalPlayableCell( Stage0PlayView view, double x, double y,
        float& outZ, std::string& outCap )
    {
        if ( UsesBareEarthTerrain( view ) )
        {
            auto const* geography=ActiveBareEarthKernel(view);if(!geography)return false;
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                // Material identity is the compiled surface authority, not a
                // float-round-tripped query just below the reconstructed mesh.
                // Near a formation contact the latter could choose a different
                // side depending on whether the package was already resident.
                auto const geology=UsesPresentWaterOccupancy(view)&&ActivePresentWaterKernel()
                    ?ActivePresentWaterKernel()->SurfaceGeology(x,y)
                    :(IsCompiledSedimentView(view)&&g.compiledSedimentRuntime
                    ?g.compiledSedimentRuntime->SurfaceGeology(x,y)
                    :(IsCompiledFluvialErosionView(view)&&g.compiledFluvialRuntime
                        ?g.compiledFluvialRuntime->SurfaceGeology(x,y):geography->SurfaceGeology(x,y)));
                if(!geology.found)return false;
                outCap=geology.material;return true;
            }
            outZ=(float)(UsesPresentWaterOccupancy(view)&&ActivePresentWaterKernel()
                ?ActivePresentWaterKernel()->ReconstructedZ(x,y)
                :(IsCompiledSedimentView(view)&&g.compiledSedimentRuntime
                ?g.compiledSedimentRuntime->ReconstructedZ(x,y)
                :(IsCompiledFluvialErosionView(view)&&g.compiledFluvialRuntime
                    ?g.compiledFluvialRuntime->ReconstructedZ(x,y):geography->ReconstructedZ(x,y))));
            auto const geology=UsesPresentWaterOccupancy(view)&&ActivePresentWaterKernel()
                ?ActivePresentWaterKernel()->SurfaceGeology(x,y)
                :(IsCompiledSedimentView(view)&&g.compiledSedimentRuntime
                ?g.compiledSedimentRuntime->SurfaceGeology(x,y)
                :(IsCompiledFluvialErosionView(view)&&g.compiledFluvialRuntime
                    ?g.compiledFluvialRuntime->SurfaceGeology(x,y):geography->SurfaceGeology(x,y)));
            if(!geology.found)return false;
            outCap=geology.material;return true;
        }
        if ( UsesExactLocalMaterialization( view ) )
        {
            if(!g.exactLocalRuntime||!g.causalBreachRuntime)return false;
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                auto const geology=g.exactLocalRuntime->Owns(x,y)
                    ?(IsSinglePickProofView(view)&&g.singlePickRuntime
                        ?g.singlePickRuntime->Query(*g.exactLocalRuntime,x,y,(double)outZ-0.001)
                        :g.exactLocalRuntime->Query(x,y,(double)outZ-0.001))
                    :g.causalBreachRuntime->Query(x,y,(double)outZ-0.001);
                if(!geology.found)return false;outCap=geology.material;return true;
            }
            outZ=(float)(IsSinglePickProofView(view)&&g.singlePickRuntime
                ?CausalSinglePickProof::IntegratedSurfaceZ(*g.singlePickRuntime,
                    *g.exactLocalRuntime,*g.causalBreachRuntime,x,y)
                :CausalExactLocalMaterialization::IntegratedSurfaceZ(
                    *g.exactLocalRuntime,*g.causalBreachRuntime,x,y));
            auto const geology=g.exactLocalRuntime->Owns(x,y)
                ?(IsSinglePickProofView(view)&&g.singlePickRuntime
                    ?g.singlePickRuntime->Query(*g.exactLocalRuntime,x,y,(double)outZ-0.001)
                    :g.exactLocalRuntime->SurfaceSample(x,y))
                :g.causalBreachRuntime->SurfaceGeology(x,y);
            if(!geology.found)return false;outCap=geology.material;return true;
        }
        if ( IsSurfaceBreachView( view ) )
        {
            if(!g.causalBreachRuntime)return false;
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                auto const material=g.causalBreachRuntime->QueryMaterial(
                    x,y,(double)outZ-0.001);
                if(!material.found||!material.material)return false;
                outCap=material.material;return true;
            }
            outZ=(float)g.causalBreachRuntime->ReconstructedZ(x,y);
            auto const geology=g.causalBreachRuntime->SurfaceGeology(x,y);
            if(!geology.found)return false;outCap=geology.material;return true;
        }
        if ( IsFaultDisplacementView( view ) )
        {
            if ( !g.causalFaultRuntime ) { return false; }
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                auto const material=g.causalFaultRuntime->QueryMaterial(
                    true,x,y,(double)outZ-0.001);
                if(!material.found||!material.material)return false;
                outCap=material.material;return true;
            }
            outZ = (float)g.causalFaultRuntime->ReconstructedZ( x, y );
            auto const geology = g.causalFaultRuntime->SurfaceGeology( true, x, y );
            if ( !geology.found ) { return false; }
            outCap = geology.material; return true;
        }
        if ( IsCutCOccupancyView( view ) )
        {
            if ( !g.cutCOccupancyRuntime || !g.causalMineralizationRuntime )
            { return false; }
            outZ=(float)CutCOccupancy::IntegratedSurfaceZ(*g.cutCOccupancyRuntime,
                *g.causalMineralizationRuntime,x,y);
            if ( g.cutCOccupancyRuntime->Owns( x, y ) )
            {
                auto const geology = g.cutCOccupancyRuntime->SurfaceSample( x, y );
                if ( !geology.found ) { return false; }
                outCap = geology.material; return true;
            }
            // The finite Cut-C proof sits in the unchanged Stage-10 control
            // world.  Only coordinates inside the proof region switch source.
            auto const geology = g.causalMineralizationRuntime->Query(true,x,y,outZ-0.001);
            if ( !geology.found ) { return false; }
            outCap = geology.material; return true;
        }
        if ( IsCausalGeologyView( view ) )
        {
            if ( !g.causalGeologyRuntime ) { return false; }
            outZ = 0.0f;
            CausalWorldGeology::GeoSample const sample =
                g.causalGeologyRuntime->Query( x, y, -0.001 );
            if ( !sample.found ) { return false; }
            outCap = sample.material;
            return true;
        }
        if ( IsContactMineralizationView( view ) )
        {
            if ( !g.causalMineralizationRuntime ) { return false; }
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                auto const material=g.causalMineralizationRuntime->QueryMaterial(
                    true,x,y,(double)outZ-0.001);
                if(!material.found||!material.material)return false;
                outCap=material.material;return true;
            }
            outZ = (float)g.causalMineralizationRuntime->ReconstructedZ( x, y );
            auto const geology = g.causalMineralizationRuntime->SurfaceGeology( true, x, y );
            if ( !geology.found ) { return false; }
            outCap = geology.material;
            return true;
        }
        if ( IsGraniteIntrusionView( view ) )
        {
            if ( !g.causalIntrusionRuntime ) { return false; }
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                auto const material=g.causalIntrusionRuntime->QueryMaterial(
                    true,x,y,(double)outZ-0.001);
                if(!material.found||!material.material)return false;
                outCap=material.material;return true;
            }
            outZ = (float)g.causalIntrusionRuntime->ReconstructedZ( x, y );
            auto const geology = g.causalIntrusionRuntime->SurfaceGeology( true, x, y );
            if ( !geology.found ) { return false; }
            outCap = geology.material;
            return true;
        }
        if ( IsDifferentialErosionView( view ) )
        {
            if ( !g.causalErosionRuntime ) { return false; }
            if(SampleResidentCausalPackageSurface(x,y,outZ))
            {
                auto const material=g.causalErosionRuntime->Exposure().Geology()
                    .QueryMaterial(x,y,(double)outZ-0.001);
                if(!material.found||!material.material)return false;
                outCap=material.material;return true;
            }
            auto const sample = g.causalErosionRuntime->Query( g.stage8Control, x, y );
            if ( !sample.found ) { return false; }
            outZ = (float)g.causalErosionRuntime->ReconstructedZ( g.stage8Control, x, y );
            outCap = sample.geology.material;
            return true;
        }
        if ( IsCausalExposureView( view ) )
        {
            if ( !g.causalExposureRuntime ) { return false; }
            CausalWorldExposure::ExposureSample const sample =
                g.causalExposureRuntime->Query( CausalWorldExposure::kPresentSurface, x, y );
            if ( !sample.found ) { return false; }
            outZ = (float)sample.surfaceZ;
            outCap = sample.geology.material;
            return true;
        }
        if ( IsVisibleExposureView( view ) )
        {
            if ( !g.causalVisibleRuntime ) { return false; }
            CausalWorldExposure::ExposureSample const sample =
                g.causalVisibleRuntime->AuthorityAt( x, y );
            if ( !sample.found ) { return false; }
            outZ = (float)g.causalVisibleRuntime->ReconstructedZ( x, y );
            outCap = sample.geology.material;
            return true;
        }
        return false;
    }

    CausalWorldGeology::GeoSample CausalGeologyAt(
        Stage0PlayView view, double x, double y, double z )
    {
        if(UsesPresentWaterOccupancy(view)&&ActivePresentWaterKernel())
        {
            double const surface=ActivePresentWaterKernel()->ReconstructedZ(x,y);
            if(z>=surface-0.05)return ActivePresentWaterKernel()->SurfaceGeology(x,y);
            return ActivePresentWaterKernel()->QueryGeology(x,y,z);
        }
        if(IsCompiledSedimentView(view)&&g.compiledSedimentRuntime)
        {
            double const surface=g.compiledSedimentRuntime->ReconstructedZ(x,y);
            if(z>=surface-0.05)return g.compiledSedimentRuntime->SurfaceGeology(x,y);
            return g.compiledSedimentRuntime->QueryGeology(x,y,z);
        }
        if(UsesBareEarthTerrain(view))
        {auto const* geography=ActiveBareEarthKernel(view);if(geography)return geography->Query(x,y,z);}
        if(IsSinglePickProofView(view)&&g.singlePickRuntime&&g.exactLocalRuntime
          &&g.exactLocalRuntime->Owns(x,y))return g.singlePickRuntime->Query(*g.exactLocalRuntime,x,y,z);
        if(UsesExactLocalMaterialization(view)&&g.exactLocalRuntime
          &&g.exactLocalRuntime->Owns(x,y))return g.exactLocalRuntime->Query(x,y,z);
        if(UsesExactLocalMaterialization(view)&&g.causalBreachRuntime)
        {return g.causalBreachRuntime->Query(x,y,z);}
        if(IsSurfaceBreachView(view)&&g.causalBreachRuntime)
        {return g.causalBreachRuntime->Query(x,y,z);}
        if ( IsFaultDisplacementView( view ) && g.causalFaultRuntime )
        { return g.causalFaultRuntime->Query( true, x, y, z ); }
        if ( IsCutCOccupancyView( view ) && g.cutCOccupancyRuntime
          && g.cutCOccupancyRuntime->Owns( x, y ) )
        { return g.cutCOccupancyRuntime->Query( x, y, z ); }
        if ( IsCutCOccupancyView( view ) && g.causalMineralizationRuntime )
        { return g.causalMineralizationRuntime->Query( true, x, y, z ); }
        if ( IsCausalGeologyView( view ) && g.causalGeologyRuntime )
        { return g.causalGeologyRuntime->Query( x, y, z ); }
        if ( IsCausalExposureView( view ) && g.causalExposureRuntime )
        { return g.causalExposureRuntime->Geology().Query( x, y, z ); }
        if ( IsVisibleExposureView( view ) && g.causalVisibleRuntime )
        { return g.causalVisibleRuntime->Exposure().Geology().Query( x, y, z ); }
        if ( IsDifferentialErosionView( view ) && g.causalErosionRuntime )
        { return g.causalErosionRuntime->Exposure().Geology().Query( x, y, z ); }
        if ( IsGraniteIntrusionView( view ) && g.causalIntrusionRuntime )
        { return g.causalIntrusionRuntime->Query( true, x, y, z ); }
        if ( IsContactMineralizationView( view ) && g.causalMineralizationRuntime )
        { return g.causalMineralizationRuntime->Query( true, x, y, z ); }
        return {};
    }

    CausalWorldGeology::MaterialSample CausalMaterialAt(
        Stage0PlayView view, double x, double y, double z )
    {
        if(UsesPresentWaterOccupancy(view)&&ActivePresentWaterKernel())
        {
            double const surface=ActivePresentWaterKernel()->ReconstructedZ(x,y);
            if(z>=surface-0.05)
            {
                auto const geology=ActivePresentWaterKernel()->SurfaceGeology(x,y);
                if(!geology.found)return {};
                char const* material=
                    geology.material=="shale"?"shale":
                    geology.material=="sandstone"?"sandstone":
                    geology.material=="granite"?"granite":
                    geology.material=="quartz"?"quartz":"dirt";
                return {true,material,
                    geology.chronology.empty()?0u:geology.chronology.back()};
            }
            return ActivePresentWaterKernel()->Geography().QueryMaterial(x,y,z);
        }
        if(IsCompiledSedimentView(view)&&g.compiledSedimentRuntime)
        {
            double const surface=g.compiledSedimentRuntime->ReconstructedZ(x,y);
            if(z>=surface-0.05)
            {
                auto const geology=g.compiledSedimentRuntime->SurfaceGeology(x,y);
                if(!geology.found)return {};
                char const* material=
                    geology.material=="shale"?"shale":
                    geology.material=="sandstone"?"sandstone":
                    geology.material=="granite"?"granite":
                    geology.material=="quartz"?"quartz":"dirt";
                return {true,material,
                    geology.chronology.empty()?0u:geology.chronology.back()};
            }
            return g.compiledSedimentRuntime->Geography().QueryMaterial(x,y,z);
        }
        if(UsesBareEarthTerrain(view))
        {auto const* geography=ActiveBareEarthKernel(view);if(geography)return geography->QueryMaterial(x,y,z);}
        if(IsSinglePickProofView(view)&&g.singlePickRuntime&&g.exactLocalRuntime
          &&g.exactLocalRuntime->Owns(x,y))
            return g.singlePickRuntime->QueryMaterial(*g.exactLocalRuntime,x,y,z);
        if(UsesExactLocalMaterialization(view)&&g.exactLocalRuntime
          &&g.exactLocalRuntime->Owns(x,y))return g.exactLocalRuntime->QueryMaterial(x,y,z);
        if(UsesExactLocalMaterialization(view)&&g.causalBreachRuntime)
        {return g.causalBreachRuntime->QueryMaterial(x,y,z);}
        if(IsSurfaceBreachView(view)&&g.causalBreachRuntime)
        {return g.causalBreachRuntime->QueryMaterial(x,y,z);}
        if ( IsFaultDisplacementView( view ) && g.causalFaultRuntime )
        { return g.causalFaultRuntime->QueryMaterial( true, x, y, z ); }
        if ( IsGraniteIntrusionView( view ) && g.causalIntrusionRuntime )
        { return g.causalIntrusionRuntime->QueryMaterial( true, x, y, z ); }
        if ( ( IsContactMineralizationView( view ) || IsCutCOccupancyView( view ) )
          && g.causalMineralizationRuntime )
        { return g.causalMineralizationRuntime->QueryMaterial( true, x, y, z ); }
        if ( IsDifferentialErosionView( view ) && g.causalErosionRuntime )
        { return g.causalErosionRuntime->Exposure().Geology().QueryMaterial( x, y, z ); }
        if ( IsVisibleExposureView( view ) && g.causalVisibleRuntime )
        { return g.causalVisibleRuntime->Exposure().Geology().QueryMaterial( x, y, z ); }
        if ( IsCausalExposureView( view ) && g.causalExposureRuntime )
        { return g.causalExposureRuntime->Geology().QueryMaterial( x, y, z ); }
        if ( IsCausalGeologyView( view ) && g.causalGeologyRuntime )
        { return g.causalGeologyRuntime->QueryMaterial( x, y, z ); }
        return {};
    }

    void EnsureGeoCell( int cx, int cy )
    {
        float sampleGrade = g.gradeDatum;
        std::string sampleCap = "dirt";
        if ( ( g.playWorldgenBaseline || g.certStage8Perf || g.certWorldgenLadderAudit
          || g.certWorldgenLadderLivePerf )
          && IsCausalPlayableView( g.stage0PlayView ) )
        {
            float surfaceZ = 0.0f;
            if ( !SampleCausalPlayableCell( g.stage0PlayView,
                    (double)cx + 0.5, (double)cy + 0.5, surfaceZ, sampleCap ) )
            {
                g.statusLine = "CAUSAL WORLD REFUSED - authoritative sample unavailable";
                return;
            }
            float const scale = g.reliefVoxels * g.voxelEdgeM;
            if ( scale <= 0.0f )
            {
                g.statusLine = "CAUSAL WORLD REFUSED - invalid grade scale";
                return;
            }
            sampleGrade = g.gradeDatum + surfaceZ / scale;
        }
        else
        {
            ProvenanceGeo::EnsureReady();
            auto const sample = ProvenanceGeo::SampleSurface(
                (double)cx + 0.5, (double)cy + 0.5,
                g.gradeDatum, g.reliefVoxels, g.voxelEdgeM );
            sampleGrade = sample.grade;
            sampleCap = sample.cap;
        }
        auto const key = CellKey( cx, cy );
        CellSample& dest = g.cells[key];
        bool const keepFillZ = dest.valid && dest.hasFillZ;
        float const keepFZ = dest.fillZ;
        bool const keepEdited = dest.valid && dest.edited;
        bool const keepCarved = dest.valid && dest.carved;
        bool const keepCavity = dest.valid && dest.hasCavity;
        GLuint const keepCavityList = dest.valid ? dest.cavityList : 0;
        bool const keepFocus = dest.valid && dest.hasCarveFocus;
        float const kWx = dest.carveWx, kWy = dest.carveWy, kWz = dest.carveWz, kRM = dest.carveRM;
        bool const keepPatch = dest.valid && dest.hasPatchBounds;
        float const pMnX = dest.patchMinX, pMnY = dest.patchMinY, pMxX = dest.patchMaxX, pMxY = dest.patchMaxY;
        uint32_t const keepRegionId = dest.valid ? dest.editedRegionId : 0;
        if ( !dest.valid )
        {
            ++g.cellsLoaded;
            ++g.perfGeoCellsCreated;
        }
        ++g.perfSampleSurfaceCalls; // geography FBM — once per cell create/refresh, not per tri
        // Esoterica geography = baseline grade/cap authority (bridge optional).
        dest.grade = sampleGrade;
        dest.cap = sampleCap;
        CapColor( sampleCap.c_str(), dest.r, dest.g, dest.b );
        dest.valid = true;
        // Preserve dig flags — never promote resident fill into "edited/carved" on stream refresh.
        if ( keepFillZ )
        {
            dest.hasFillZ = true;
            dest.fillZ = keepFZ;
        }
        if ( keepEdited ) { dest.edited = true; }
        if ( keepCarved )
        {
            dest.carved = true;
            dest.hasCavity = keepCavity;
            dest.cavityList = keepCavityList;
        }
        if ( keepFocus )
        {
            dest.hasCarveFocus = true;
            dest.carveWx = kWx; dest.carveWy = kWy; dest.carveWz = kWz; dest.carveRM = kRM;
        }
        if ( keepPatch )
        {
            dest.hasPatchBounds = true;
            dest.patchMinX = pMnX; dest.patchMinY = pMnY;
            dest.patchMaxX = pMxX; dest.patchMaxY = pMxY;
        }
        if ( keepRegionId != 0 ) { dest.editedRegionId = keepRegionId; }
    }

    void EnsureGeoDisk( int px, int py, int radCells )
    {
        LARGE_INTEGER q0{}, q1{}, qpf{};
        QueryPerformanceFrequency( &qpf );
        QueryPerformanceCounter( &q0 );
        ++g.perfGeoDiskRequests;
        bool any = false;
        int requested = 0;
        double pureGenerationMs = 0.0;
        for ( int dy = -radCells; dy <= radCells; ++dy )
        {
            for ( int dx = -radCells; dx <= radCells; ++dx )
            {
                if ( dx * dx + dy * dy > radCells * radCells ) { continue; }
                int const cx = px + dx, cy = py + dy;
                if ( GetCell( cx, cy ) ) { continue; }
                ++requested;
                LARGE_INTEGER gen0{}, gen1{};
                QueryPerformanceCounter( &gen0 );
                EnsureGeoCell( cx, cy );
                QueryPerformanceCounter( &gen1 );
                if ( qpf.QuadPart > 0 )
                {
                    pureGenerationMs += 1000.0 * (double)( gen1.QuadPart - gen0.QuadPart )
                        / (double)qpf.QuadPart;
                }
                if ( g.certWorldgenBaselinePerf || g.playWorldgenBaseline )
                {
                    MarkStage0TerrainVertexDirty( cx, cy );
                }
                any = true;
            }
        }
        QueryPerformanceCounter( &q1 );
        double const requestMs = qpf.QuadPart > 0
            ? 1000.0 * (double)( q1.QuadPart - q0.QuadPart ) / (double)qpf.QuadPart
            : 0.0;
        g.perfGeoCellsRequested += requested;
        g.perfGeoGenMsTotal += requestMs;
        g.perfGeoPureGenMsTotal += pureGenerationMs;
        g.perfGeoGenMsMax = (std::max)( g.perfGeoGenMsMax, requestMs );
        if ( requested == 0 ) { ++g.perfGeoDiskNoopRequests; }
        if ( g.certWorldgenBaselinePerf || g.playWorldgenBaseline )
        {
            g.stage0FrameGenerationMs += pureGenerationMs;
            g.stage0FrameResidencyMs += (std::max)( 0.0, requestMs - pureGenerationMs );
        }
        if ( any )
        {
            if ( g.certWorldgenBaselinePerf || g.playWorldgenBaseline )
            {
                // Stage 0 owns stable local presentation blocks. New vertices dirty
                // only the blocks whose quads can reference them.
                if ( !g.terrainDirty ) { ++g.perfTerrainWakes; }
                g.terrainDirty = true;
                std::snprintf( g.lastTerrainWakeReason,
                    sizeof( g.lastTerrainWakeReason ), "stage0_residency_expand" );
            }
            else
            {
                InvalidateTerrainMesh( "residency_expand" );
            }
        }
    }

    bool Stage0CellHasPersistentAuthority( CellSample const& cell )
    {
        return cell.edited || cell.carved || cell.hasFillZ || !cell.fill.empty()
            || cell.hasCavity || cell.editedRegionId != 0 || cell.hasOccCrest;
    }

    Stage0PresentationBounds Stage0CurrentPresentationBounds()
    {
        // Presentation changes package ownership only on the common 8 m package
        // cadence.  Exact and latent surfaces use this identical rectangle, so
        // residency never exposes a circular render edge.
        constexpr int kSnapM = kStage0TerrainBlockCells;
        // Live player-space extent. Exact packages cost roughly 0.19 ms each and
        // enter along the perimeter, so this scales with radius while the latent
        // far field scales with area. Widening it here also pushes the far-field
        // inner boundary outward, because the far field stitches to these same
        // bounds. Snapped to the package cadence so ownership stays on grid.
        int const kHalfM = ( g.stage0LiveRadiusM / kSnapM ) * kSnapM;
        Stage0PresentationBounds b;
        b.anchorX = FloorDivCell( (int)std::floor( g.feetX ), kSnapM ) * kSnapM;
        b.anchorY = FloorDivCell( (int)std::floor( g.feetY ), kSnapM ) * kSnapM;
        b.bx0 = FloorDivCell( b.anchorX - kHalfM, kStage0TerrainBlockCells );
        b.by0 = FloorDivCell( b.anchorY - kHalfM, kStage0TerrainBlockCells );
        b.bx1 = FloorDivCell( b.anchorX + kHalfM, kStage0TerrainBlockCells );
        b.by1 = FloorDivCell( b.anchorY + kHalfM, kStage0TerrainBlockCells );
        bool const dualSurface = IsVisibleExposureView( g.stage0PlayView )
            || IsDifferentialErosionView( g.stage0PlayView )
            || IsGraniteIntrusionView( g.stage0PlayView )
            || IsContactMineralizationView( g.stage0PlayView )
            || IsFaultDisplacementView( g.stage0PlayView )
            || IsSurfaceBreachView( g.stage0PlayView )
            || UsesExactLocalMaterialization( g.stage0PlayView )
            || UsesBareEarthTerrain( g.stage0PlayView )
            || IsCutCOccupancyView( g.stage0PlayView );
        float const dualOffset = dualSurface ? -0.25f : 0.f;
        b.minX = b.bx0 * kStage0TerrainBlockCells + dualOffset;
        b.minY = b.by0 * kStage0TerrainBlockCells + dualOffset;
        b.maxX = ( b.bx1 + 1 ) * kStage0TerrainBlockCells + dualOffset;
        b.maxY = ( b.by1 + 1 ) * kStage0TerrainBlockCells + dualOffset;
        return b;
    }

    void EvictStage0Residency( int centerX, int centerY )
    {
        if ( !g.certWorldgenBaselinePerf && !g.playWorldgenBaseline ) { return; }
        LARGE_INTEGER q0{}, q1{}, qpf{};
        QueryPerformanceFrequency( &qpf );
        QueryPerformanceCounter( &q0 );
        // Stage 13 render/collision residency is the authoritative 8 m package
        // window, not this legacy one-metre diagnostic cache.  Keep only a
        // bounded local interaction neighborhood there; retaining a second
        // 68 m causal disk made every 4 m flight step synchronously resample a
        // wide fringe on the frame thread even though the package workers had
        // already supplied the complete 192 m terrain answer.
        int const cacheRadius = UsesPackageOwnedTerrain( g.stage0PlayView )
            ? 20 : 68;
        int const cacheRadiusSq = cacheRadius * cacheRadius;

        std::vector<uint64_t> cellsToErase;
        cellsToErase.reserve( 256 );
        for ( auto const& kv : g.cells )
        {
            int const cx = (int)(int32_t)( kv.first >> 32 );
            int const cy = (int)(int32_t)( kv.first & 0xffffffffu );
            int const dx = cx - centerX;
            int const dy = cy - centerY;
            if ( dx * dx + dy * dy <= cacheRadiusSq ) { continue; }
            if ( Stage0CellHasPersistentAuthority( kv.second ) ) { continue; }
            cellsToErase.push_back( kv.first );
        }
        for ( uint64_t const key : cellsToErase )
        {
            g.cells.erase( key );
        }
        g.perfGeoCellsEvicted += (int)cellsToErase.size();
        g.playWorldgenEvicted = g.perfGeoCellsEvicted;
        g.cellsLoaded = (int)g.cells.size();

        // Presentation has its own bounded lifecycle. Keep the exact rectangular
        // ownership set (plus one package of cache) even when its corners lie
        // outside the circular authority residency.
        Stage0PresentationBounds const bounds = Stage0CurrentPresentationBounds();
        std::vector<uint64_t> blocksToErase;
        for ( auto const& kv : g.stage0TerrainBlocks )
        {
            int const bx = (int)(int32_t)( kv.first >> 32 );
            int const by = (int)(int32_t)( kv.first & 0xffffffffu );
            if ( bx < bounds.bx0 - 1 || bx > bounds.bx1 + 1
              || by < bounds.by0 - 1 || by > bounds.by1 + 1 )
            {
                blocksToErase.push_back( kv.first );
            }
        }
        for ( uint64_t const key : blocksToErase )
        {
            auto const it = g.stage0TerrainBlocks.find( key );
            if ( it == g.stage0TerrainBlocks.end() ) { continue; }
            RetireTerrainDisplayList( it->second.list );
            g.perfHfTris -= it->second.tris;
            g.stage0TerrainBlocks.erase( it );
            g.stage0DirtyTerrainBlocks.erase( key );
        }
        g.perfHfBlocksEvicted += (int)blocksToErase.size();
        QueryPerformanceCounter( &q1 );
        if ( qpf.QuadPart > 0 )
        {
            g.stage0FrameResidencyMs += 1000.0 * (double)( q1.QuadPart - q0.QuadPart )
                / (double)qpf.QuadPart;
        }
    }

    void ClearPendingScarEdit()
    {
        g.pendingScarIndex = -1;
        g.pendingScarDepthBefore = 0.f;
        g.pendingScarWasNew = false;
    }

    void RollbackPendingScarEdit()
    {
        if ( g.pendingScarIndex < 0 || g.pendingScarIndex >= (int)g.scars.size() )
        {
            ClearPendingScarEdit();
            return;
        }
        if ( g.pendingScarWasNew )
        {
            // Only pop if still the edited slot (usually back)
            if ( g.pendingScarIndex == (int)g.scars.size() - 1
              && g.scars.back().place == g.pendingScarIsPlace )
            {
                g.scars.pop_back();
                ++g.scarGen;
            }
        }
        else
        {
            DigScar& s = g.scars[(size_t)g.pendingScarIndex];
            if ( s.place == g.pendingScarIsPlace )
            {
                s.depth = g.pendingScarDepthBefore;
                if ( s.depth < 1e-4f )
                {
                    g.scars.erase( g.scars.begin() + g.pendingScarIndex );
                }
                ++g.scarGen;
            }
        }
        ClearPendingScarEdit();
    }

    void RemoveLastOptimisticDigScar()
    {
        if ( g.pendingScarIndex >= 0 && !g.pendingScarIsPlace )
        {
            RollbackPendingScarEdit();
            return;
        }
        if ( g.scars.empty() ) { return; }
        DigScar const& s = g.scars.back();
        if ( !s.place )
        {
            g.scars.pop_back();
            ++g.scarGen;
        }
    }

    void RemoveLastOptimisticPlaceScar()
    {
        if ( g.pendingScarIndex >= 0 && g.pendingScarIsPlace )
        {
            RollbackPendingScarEdit();
            return;
        }
        if ( g.scars.empty() ) { return; }
        DigScar const& s = g.scars.back();
        if ( s.place )
        {
            g.scars.pop_back();
            ++g.scarGen;
        }
    }

    void CancelDigScarsUnderPlace( float wx, float wy, float radius )
    {
        // Place into a hole: shrink overlapping dig cups (slump fill) instead of deleting the well wholesale.
        float const lim = radius * 0.85f;
        float const lim2 = lim * lim;
        size_t const before = g.scars.size();
        for ( DigScar& s : g.scars )
        {
            if ( s.place ) { continue; }
            float const dx = s.wx - wx;
            float const dy = s.wy - wy;
            if ( ( dx * dx + dy * dy ) > lim2 ) { continue; }
            s.depth = (std::max)( 0.f, s.depth - kHandfulRadiusM );
        }
        g.scars.erase( std::remove_if( g.scars.begin(), g.scars.end(),
            []( DigScar const& s ) { return !s.place && s.depth < 1e-4f; } ),
            g.scars.end() );
        if ( g.scars.size() != before ) { ++g.scarGen; }
    }

    void CancelPlaceScarsUnderDig( float wx, float wy, float radius )
    {
        // Dig into a mound: cut place cups so placed dirt can be scooped again.
        float const lim = radius * 0.85f;
        float const lim2 = lim * lim;
        size_t const before = g.scars.size();
        for ( DigScar& s : g.scars )
        {
            if ( !s.place ) { continue; }
            float const dx = s.wx - wx;
            float const dy = s.wy - wy;
            if ( ( dx * dx + dy * dy ) > lim2 ) { continue; }
            s.depth = (std::max)( 0.f, s.depth - kHandfulRadiusM );
        }
        g.scars.erase( std::remove_if( g.scars.begin(), g.scars.end(),
            []( DigScar const& s ) { return s.place && s.depth < 1e-4f; } ),
            g.scars.end() );
        if ( g.scars.size() != before ) { ++g.scarGen; }
    }

    void RemoveDigScarsInCell( int cx, int cy )
    {
        size_t const before = g.scars.size();
        g.scars.erase( std::remove_if( g.scars.begin(), g.scars.end(),
            [&]( DigScar const& s ) { return !s.place && s.cx == cx && s.cy == cy; } ),
            g.scars.end() );
        if ( g.scars.size() != before ) { ++g.scarGen; }
    }

    void PruneScars()
    {
        // Prefer distance cull over FIFO — old nearby holes must not vanish when you dig elsewhere.
        float const maxR = (float)kFarRadiusCells + 4.f;
        float const maxR2 = maxR * maxR;
        g.scars.erase( std::remove_if( g.scars.begin(), g.scars.end(),
            [&]( DigScar const& s )
            {
                float const dx = s.wx - g.feetX;
                float const dy = s.wy - g.feetY;
                return ( dx * dx + dy * dy ) > maxR2;
            } ),
            g.scars.end() );
        // Dense handful fields easily exceed a few hundred cups; keep nearby openings alive.
        constexpr size_t kScarSoftCap = 8192;
        while ( g.scars.size() > kScarSoftCap )
        {
            // Drop farthest from feet, never a random "first dug" near the player
            size_t worst = 0;
            float worstD2 = -1.f;
            for ( size_t i = 0; i < g.scars.size(); ++i )
            {
                float const dx = g.scars[i].wx - g.feetX;
                float const dy = g.scars[i].wy - g.feetY;
                float const d2 = dx * dx + dy * dy;
                if ( d2 > worstD2 ) { worstD2 = d2; worst = i; }
            }
            g.scars.erase( g.scars.begin() + (std::ptrdiff_t)worst );
        }
    }

    void AddScar( float wx, float wy, float wz, int cx, int cy, bool place, bool tunnel )
    {
        // Place: tight merge. Dig: deepen only when reticle is near the SAME scoop centre.
        // Wide dig-merge glued rim-overlap digs into the old hole (remaining solid never got a cup).
        float const mergeR = kHandfulRadiusM * ( place ? 0.35f : 0.42f );
        float const mergeR2 = mergeR * mergeR;
        for ( size_t i = 0; i < g.scars.size(); ++i )
        {
            DigScar& s = g.scars[i];
            if ( s.place != place ) { continue; }
            if ( !place && s.tunnel != tunnel ) { continue; } // open shaft ≠ buried tunnel
            float const dx = s.wx - wx;
            float const dy = s.wy - wy;
            if ( ( dx * dx + dy * dy ) > mergeR2 ) { continue; }
            if ( !place )
            {
                // Near bowl centre only — rim / remaining-solid bites get their own cup.
                if ( ScarHemiAt( s, wx, wy ) < kHandfulRadiusM * 0.55f ) { continue; }
            }
            g.pendingScarIndex = (int)i;
            g.pendingScarDepthBefore = s.depth;
            g.pendingScarWasNew = false;
            g.pendingScarIsPlace = place;
            s.depth += kHandfulRadiusM;
            if ( place )
            {
                s.wz = wz;
            }
            else if ( s.tunnel )
            {
                s.wz = (std::min)( s.wz, wz ); // deepen cavity centre
            }
            else
            {
                s.wz = wz;
            }
            ++g.scarGen;
            auto it = g.cells.find( CellKey( s.cx, s.cy ) );
            if ( it != g.cells.end() && it->second.valid ) { it->second.edited = true; }
            return;
        }

        DigScar s;
        s.wx = wx; s.wy = wy; s.wz = wz;
        s.cx = cx; s.cy = cy;
        s.place = place;
        s.tunnel = place ? false : tunnel;
        s.entranceWz = wz;
        s.radius = ( g.pendingAffectRM > 1e-5f ) ? g.pendingAffectRM : SoftScoopScarRadiusM();
        s.depth = s.radius;
        s.kind = ScarKind::ScoopHemi;
        g.scars.push_back( s );
        g.pendingScarIndex = (int)g.scars.size() - 1;
        g.pendingScarDepthBefore = 0.f;
        g.pendingScarWasNew = true;
        g.pendingScarIsPlace = place;
        ++g.scarGen;
        PruneScars();
        if ( g.pendingScarWasNew )
        {
            g.pendingScarIndex = (int)g.scars.size() - 1;
        }
        auto it = g.cells.find( CellKey( cx, cy ) );
        if ( it != g.cells.end() && it->second.valid ) { it->second.edited = true; }
    }

    bool IsSteepFaceAt( float x, float y )
    {
        // Flat ground nz≈1; vertical cliff nz→0. Hemi DigDep on cliffs stretches into vertical scoops.
        float nx = 0.f, ny = 0.f, nz = 1.f;
        SampleAimNormal( x, y, nx, ny, nz );
        return nz < 0.58f;
    }

    void AddFacePunctureScar( float wx, float wy, float wz, int cx, int cy,
        float radius, float depthAmp, float nx, float ny, float nz )
    {
        float const mergeR = radius * 0.85f;
        float const mergeR2 = mergeR * mergeR;
        for ( size_t i = 0; i < g.scars.size(); ++i )
        {
            DigScar& s = g.scars[i];
            if ( s.place || s.kind != ScarKind::FacePuncture ) { continue; }
            float const dx = s.wx - wx, dy = s.wy - wy, dz = s.wz - wz;
            if ( ( dx * dx + dy * dy + dz * dz ) > mergeR2 ) { continue; }
            g.pendingScarIndex = (int)i;
            g.pendingScarDepthBefore = s.depth;
            g.pendingScarWasNew = false;
            g.pendingScarIsPlace = false;
            s.depth = (std::min)( 0.08f, s.depth + depthAmp * 0.35f );
            s.radius = (std::max)( s.radius, radius );
            s.wx = wx; s.wy = wy; s.wz = wz;
            s.faceNx = nx; s.faceNy = ny; s.faceNz = nz;
            ++g.scarGen;
            return;
        }
        DigScar s;
        s.wx = wx; s.wy = wy; s.wz = wz;
        s.cx = cx; s.cy = cy;
        s.place = false;
        s.tunnel = false;
        s.entranceWz = wz;
        s.kind = ScarKind::FacePuncture;
        s.radius = radius;
        s.depth = depthAmp;
        s.support = 1.f;
        s.faceNx = nx; s.faceNy = ny; s.faceNz = nz;
        g.scars.push_back( s );
        g.pendingScarIndex = (int)g.scars.size() - 1;
        g.pendingScarDepthBefore = 0.f;
        g.pendingScarWasNew = true;
        g.pendingScarIsPlace = false;
        ++g.scarGen;
        PruneScars();
        if ( g.pendingScarWasNew )
        {
            g.pendingScarIndex = (int)g.scars.size() - 1;
        }
    }

    // Foliation plate notch — merge extends the SAME seam (impact → crack → pry → plate).
    void AddFoliationPlateScar( float wx, float wy, float wz, int cx, int cy,
        float strikeX, float strikeY,
        float along, float acrossDeep, float acrossLip, float depthAmp,
        float support, RockStruct::FractureStage stage,
        float faceNx, float faceNy, float faceNz )
    {
        float const inv = 1.f / (std::max)( 1e-5f, std::sqrt( strikeX * strikeX + strikeY * strikeY ) );
        strikeX *= inv; strikeY *= inv;
        float const mergeAlong = along + 0.06f;
        for ( size_t i = 0; i < g.scars.size(); ++i )
        {
            DigScar& s = g.scars[i];
            if ( s.place || s.kind != ScarKind::FoliationPlate ) { continue; }
            float const dot = s.strikeX * strikeX + s.strikeY * strikeY;
            if ( std::fabs( dot ) < 0.82f ) { continue; }
            float const dx = s.wx - wx, dy = s.wy - wy, dz = s.wz - wz;
            float const alongD = std::fabs( dx * s.strikeX + dy * s.strikeY );
            float const acrossD = std::fabs( dx * ( -s.strikeY ) + dy * s.strikeX );
            if ( alongD > mergeAlong || acrossD > acrossDeep + 0.05f ) { continue; }
            if ( ( dx * dx + dy * dy + dz * dz ) > ( mergeAlong * mergeAlong ) ) { continue; }

            g.pendingScarIndex = (int)i;
            g.pendingScarDepthBefore = s.depth;
            g.pendingScarWasNew = false;
            g.pendingScarIsPlace = false;
            s.plateAlong = (std::min)( RockStruct::kStructuralSlabM * 0.55f, s.plateAlong + along * 0.35f );
            s.plateAcrossDeep = (std::max)( s.plateAcrossDeep, acrossDeep );
            s.plateAcrossLip = (std::min)( s.plateAcrossLip, acrossLip );
            s.depth = (std::max)( s.depth, depthAmp );
            s.support = (std::min)( s.support, support );
            s.fracStage = stage;
            s.wx = wx; s.wy = wy; s.wz = wz; // extend from latest strike contact
            s.faceNx = faceNx; s.faceNy = faceNy; s.faceNz = faceNz;
            ++g.scarGen;
            auto it = g.cells.find( CellKey( s.cx, s.cy ) );
            if ( it != g.cells.end() && it->second.valid ) { it->second.edited = true; }
            return;
        }

        DigScar s;
        s.wx = wx; s.wy = wy; s.wz = wz;
        s.cx = cx; s.cy = cy;
        s.place = false;
        s.tunnel = false;
        s.entranceWz = wz;
        s.kind = ScarKind::FoliationPlate;
        s.strikeX = strikeX; s.strikeY = strikeY;
        s.plateAlong = along;
        s.plateAcrossDeep = acrossDeep;
        s.plateAcrossLip = acrossLip;
        s.depth = depthAmp;
        s.radius = (std::max)( along, acrossDeep );
        s.support = support;
        s.fracStage = stage;
        s.faceNx = faceNx; s.faceNy = faceNy; s.faceNz = faceNz;
        g.scars.push_back( s );
        g.pendingScarIndex = (int)g.scars.size() - 1;
        g.pendingScarDepthBefore = 0.f;
        g.pendingScarWasNew = true;
        g.pendingScarIsPlace = false;
        ++g.scarGen;
        PruneScars();
        if ( g.pendingScarWasNew )
        {
            g.pendingScarIndex = (int)g.scars.size() - 1;
        }
        auto it = g.cells.find( CellKey( cx, cy ) );
        if ( it != g.cells.end() && it->second.valid ) { it->second.edited = true; }
    }

    bool DigShouldTunnel( float wx, float wy, float wz, int cx, int cy )
    {
        // Open lit scoops only — buried tunnel spheres draped grade into holes (rejected).
        (void)wx; (void)wy; (void)wz; (void)cx; (void)cy;
        return false;
    }

    float WorldToEngDepth( float meters )
    {
        // Engine carve/place depth+radius are cell-depths (Unreal: worldΔZ / (sublayers*voxelEdge)).
        return meters / (std::max)( 0.05f, g.cellDepthM );
    }

    float HandfulRadiusEng()
    {
        // Wire carve/place radius = dig-volume / place-volume sphere (tool×material affect).
        float r = g.aimHit ? AimDigAffect().radiusM : TransferScarRadiusM();
        if ( g.pendingAffectRM > 1e-5f && g.pending != PendingKind::None )
        {
            r = g.pendingAffectRM;
        }
        return WorldToEngDepth( r );
    }

    // Dig stays under the reticle and cuts DEEPER; place keeps slump-into-hole / seat-on-mound.
    // Out depth is WORLD meters below grade (caller converts to engine cell-depths for the wire).
    void ResolveBiteFromAim( bool place,
        float& bx, float& by, float& bz,
        int& cx, int& cy, float& u, float& v, float& depthM )
    {
        float cp = std::cos( g.pitch ), sp = std::sin( g.pitch );
        float cyw = std::cos( g.yaw ), sy = std::sin( g.yaw );
        float fx = sy * cp, fy = cyw * cp, fz = sp;

        if ( place )
        {
            float const dig = DigDepAt( g.aimX, g.aimY );
            float const lift = PlaceLiftAt( g.aimX, g.aimY );
            float const netHole = dig - lift;
            // Keep slump-into-hole: only bias depth when there is a real open pit under the aim.
            if ( netHole > kHandfulRadiusM * 0.25f )
            {
                depthM = netHole;
                float const bias = kHandfulRadiusM * 0.25f;
                bx = g.aimX + fx * bias;
                by = g.aimY + fy * bias;
                bz = g.aimZ + fz * bias;
            }
            else
            {
                // Place on grade or on an existing mound — seat on contact (place-on-place).
                depthM = 0.f;
                bx = g.aimX;
                by = g.aimY;
                bz = g.aimZ;
            }
            cx = (int)std::floor( bx );
            cy = (int)std::floor( by );
            u = bx - (float)cx;
            v = by - (float)cy;
            return;
        }

        // DIG — continue along look through matter (into the face ahead of an open scoop).
        // Straight-down only when looking steeply at virgin grade. Inside a dig with a shallow
        // look, walk the bite centre FORWARD into remaining solid — never sky skin / vertical deepen.
        float hitX = g.aimX, hitY = g.aimY, hitZ = g.aimZ;
        float const R = g.aimHit ? AimDigAffect().radiusM : SoftScoopScarRadiusM();
        float const lookDown = -fz; // pitch<0 → looking down

        float crestAtAim = hitZ;
        SampleGroundZBase( hitX, hitY, crestAtAim );
        hitZ = g.aimZ;

        float nx = 0.f, ny = 0.f, nz = 1.f;
        CaptureFaceNormalAt( hitX, hitY, nx, ny, nz );
        bool const steepFace = nz < 0.58f;

        // Steep / wall contact: land ON the ray hit and press into the face along look.
        // Grade-Z re-seat + XY walk is what made vertical strikes miss the strike point.
        if ( steepFace )
        {
            float const into = R * 0.60f;
            bx = hitX + fx * into;
            by = hitY + fy * into;
            bz = hitZ + fz * into;
            cx = (int)std::floor( bx );
            cy = (int)std::floor( by );
            u = bx - (float)cx;
            v = by - (float)cy;
            depthM = R;
            return;
        }

        float const digAim = DigDepAt( hitX, hitY );
        bool const inScoop = digAim > R * 0.20f;
        bool const lookForward = lookDown < 0.72f;

        float bias = R * 0.60f;
        if ( inScoop && lookForward ) { bias = R * 2.2f; }
        else if ( lookForward ) { bias = R * 1.05f; }

        bx = hitX + fx * bias;
        by = hitY + fy * bias;
        bz = hitZ + fz * bias;

        // Walk along look until DigDep drops (solid wall ahead) — matter-true forward bite.
        if ( inScoop && lookForward )
        {
            bool foundSolid = false;
            float bestX = bx, bestY = by, bestZ = bz;
            float const tMax = R * 5.5f;
            float const tStep = R * 0.22f;
            for ( float t = R * 0.35f; t <= tMax; t += tStep )
            {
                float const x = hitX + fx * t;
                float const y = hitY + fy * t;
                float const z = hitZ + fz * t;
                float grade = 0.f;
                if ( !SampleGroundZBase( x, y, grade ) ) { continue; }
                float const dig = DigDepAt( x, y );
                // Solid = little/no open cup under grade, and bite sits in the mass (not above sky skin).
                if ( dig < R * 0.18f && z <= grade + R * 0.15f && z >= grade - R * 3.5f )
                {
                    bestX = x;
                    bestY = y;
                    // Seat just inside the face so the sphere intersects remaining solid.
                    bestZ = (std::min)( z, grade - R * 0.35f );
                    foundSolid = true;
                    break;
                }
            }
            if ( foundSolid )
            {
                bx = bestX;
                by = bestY;
                bz = bestZ;
            }
        }
        else
        {
            // Only pull back if look-steer dove INTO a deeper empty cup than the aim.
            float const digCentre = DigDepAt( bx, by );
            if ( digCentre > digAim + R * 0.25f && digCentre > R * 0.40f )
            {
                bias = R * 0.20f;
                bx = hitX + fx * bias;
                by = hitY + fy * bias;
                bz = hitZ + fz * bias;
            }
        }

        // Grade-normal seat only for steep virgin scoops — +Z nudge kills forward tunneling.
        if ( !inScoop && !lookForward && lookDown >= 0.72f )
        {
            float const pen = -( ( bx - hitX ) * nx + ( by - hitY ) * ny + ( bz - hitZ ) * nz );
            float const want = R * 0.35f;
            if ( pen < want )
            {
                float const d = want - pen;
                bx -= nx * d;
                by -= ny * d;
                bz -= nz * d;
            }
        }

        cx = (int)std::floor( bx );
        cy = (int)std::floor( by );
        u = bx - (float)cx;
        v = by - (float)cy;

        float crestZ = crestAtAim;
        SampleGroundZBase( bx, by, crestZ );
        depthM = (std::max)( R, crestZ - bz );

        // Vertical deepen only when looking down into the same cup (not forward into a face).
        if ( !lookForward && DigDepAt( bx, by ) > R * 0.70f )
        {
            float floorZ = bz;
            SampleGroundZ( bx, by, floorZ );
            float const floorDepthM = crestZ - floorZ;
            depthM = (std::max)( depthM, floorDepthM + R * 0.5f );
        }
    }

    void QueueColumn( int cx, int cy )
    {
        for ( auto const& p : g.columnQueue )
        {
            if ( p.first == cx && p.second == cy ) { return; }
        }
        // P4.3: refetch of already-resident occupancy is a terrain wake — count it.
        if ( CellHasOccupancy( cx, cy ) )
        {
            ++g.perfTerrainRefetches;
        }
        g.columnQueue.push_back( { cx, cy } );
    }

    void QueueSettledFromReply( std::string const& line )
    {
        size_t p = line.find( "\"settled\"" );
        if ( p == std::string::npos ) { return; }
        size_t b = line.find( '[', p );
        size_t e = line.find( ']', b );
        if ( b == std::string::npos || e == std::string::npos ) { return; }
        // settled entries are [x,y] pairs or objects — scan for integer pairs
        std::string body = line.substr( b + 1, e - b - 1 );
        char const* cur = body.c_str();
        while ( *cur )
        {
            while ( *cur && ( *cur < '0' || *cur > '9' ) && *cur != '-' ) { ++cur; }
            if ( !*cur ) { break; }
            char* end = nullptr;
            long x = strtol( cur, &end, 10 );
            if ( end == cur ) { break; }
            cur = end;
            while ( *cur && ( *cur < '0' || *cur > '9' ) && *cur != '-' ) { ++cur; }
            if ( !*cur ) { break; }
            long y = strtol( cur, &end, 10 );
            if ( end == cur ) { break; }
            cur = end;
            QueueColumn( (int)x, (int)y );
        }
    }

    void SetMouseLook( HWND hwnd, bool enabled )
    {
        g.mouseLook = enabled;
        if ( enabled )
        {
            RECT rc; GetClientRect( hwnd, &rc );
            POINT pt = { ( rc.right - rc.left ) / 2, ( rc.bottom - rc.top ) / 2 };
            ClientToScreen( hwnd, &pt );
            SetCursorPos( pt.x, pt.y );
            g.lastMouseX = ( rc.right - rc.left ) / 2;
            g.lastMouseY = ( rc.bottom - rc.top ) / 2;
            // Focus, capture and clip are acquired TOGETHER, here, so that no call
            // site can take the mouse without the keyboard. Six paths still call
            // this directly -- closing the journal, closing a menu or drawer, the
            // toggle key -- and chasing each one to add a SetFocus would leave the
            // next new path free to reintroduce the split. Owning the whole
            // contract in one place is what makes that impossible rather than
            // merely unlikely.
            SetFocus( hwnd );
            SetCapture( hwnd );
            POINT tl = { rc.left, rc.top }, br = { rc.right, rc.bottom };
            ClientToScreen( hwnd, &tl ); ClientToScreen( hwnd, &br );
            RECT clip = { tl.x, tl.y, br.x, br.y };
            ClipCursor( &clip );
            while ( ShowCursor( FALSE ) >= 0 ) {}
            g.cursorCaptured = true;
            g.gameplayInput = true;
        }
        else
        {
            // Release UNCONDITIONALLY. This was guarded by g.cursorCaptured, and
            // that flag can desynchronise from the real capture state -- Windows
            // revokes capture on its own (WM_CAPTURECHANGED, focus loss, a system
            // dialog) without telling us. Once it did, Esc released nothing while
            // g.mouseLook stayed true, so the viewport kept swallowing movement
            // keys and the cursor never came back: pressing Esc a second time did
            // nothing and Alt+Tab could not escape it. Releasing something that
            // was never captured is harmless; failing to release is a trap.
            ReleaseCapture();
            while ( ShowCursor( TRUE ) < 0 ) {}
            g.cursorCaptured = false;
            ClipCursor( nullptr );
            // Movement keys held at the moment of release would otherwise stay
            // latched, so the camera drifts once the user is back in the UI.
            for ( int i = 0; i < 256; ++i ) { g.keys[i] = false; }
        }
    }

    // ONE way into the viewport state, one way out. Nothing else may acquire
    // capture or mouse-look independently.
    //
    // The re-entry trap lived here. SetCapture routes MOUSE messages to a window;
    // WM_KEYDOWN goes to the FOCUSED window, which is a different thing. When the
    // runtime is embedded as a WS_CHILD in the ProvRender shell, keyboard focus
    // belongs to the WinForms host. The first entry worked only because the shell
    // handed focus over at startup. After Esc, focus returned to the shell, and
    // clicking the viewport re-took the mouse without ever asking for the
    // keyboard -- so look worked, WASD did not, and the surrounding buttons kept
    // receiving keystrokes. Capture and focus are now acquired together or not at
    // all.
    void EnterViewportInput( HWND hwnd ) { SetMouseLook( hwnd, true ); }

    // Any path that takes focus away from the viewport funnels through here, so
    // there is exactly one way to end up in the UI state and no path that leaves
    // the application owning the pointer.
    void ReleaseViewportInput( HWND hwnd )
    {
        g.gameplayInput = false;
        if ( g.mouseLook || g.cursorCaptured ) { SetMouseLook( hwnd, false ); }
        ClipCursor( nullptr );
    }

    void DrawWireSphere( float cx, float cy, float cz, float radius, float cr, float cg, float cb, int seg = 20 )
    {
        glColor3f( cr, cg, cb );
        glBegin( GL_LINE_LOOP );
        for ( int i = 0; i < seg; ++i )
        {
            float a = (float)i / (float)seg * 6.2831853f;
            glVertex3f( cx + std::cos( a ) * radius, cy + std::sin( a ) * radius, cz );
        }
        glEnd();
        glBegin( GL_LINE_LOOP );
        for ( int i = 0; i < seg; ++i )
        {
            float a = (float)i / (float)seg * 6.2831853f;
            glVertex3f( cx + std::cos( a ) * radius, cy, cz + std::sin( a ) * radius );
        }
        glEnd();
        glBegin( GL_LINE_LOOP );
        for ( int i = 0; i < seg; ++i )
        {
            float a = (float)i / (float)seg * 6.2831853f;
            glVertex3f( cx, cy + std::cos( a ) * radius, cz + std::sin( a ) * radius );
        }
        glEnd();
    }

