    struct Stage0InspectorFrame
    {
        float px=0.f, py=0.f, pz=0.f;
        float fx=0.f, fy=0.f, fz=-1.f;
        float rx=1.f, ry=0.f, rz=0.f;
        float ux=0.f, uy=0.f, uz=1.f;
    };

    bool Stage0GeologyInspectorFrame( Stage0InspectorFrame& out )
    {
        if ( !g.stage0ToolGeologyCutaway
          || !IsCausalPlayableView( g.stage0PlayView ) ) { return false; }
        if((g.certStage12Visual||g.certStage13Visual||g.certStage14Visual)
          &&g.causalBreachRuntime)
        {
            auto const& p=g.causalBreachRuntime->GetProgram();
            (void)p;
            constexpr float x=7.5f,y=-14.25f;
            float const z=(float)g.causalBreachRuntime->ReconstructedZ(x,y);
            if(!GetCell((int)std::floor(x),(int)std::floor(y)))return false;
            out.px=x;out.py=y;out.pz=z;
            out.fx=0.f;out.fy=0.f;out.fz=-1.f;
            out.rx=1.f;out.ry=0.f;out.rz=0.f;
            out.ux=0.f;out.uy=1.f;out.uz=0.f;
            g.stage0GeologyInspectorDepthM=1.0f;
            return true;
        }
        if ( g.certStage11Visual && g.causalFaultRuntime )
        {
            // The permanent Stage-11 visual receipt must show both halves of the
            // displaced quartz body at once.  Use a deterministic terminal plane
            // containing the certified fault throw D=(3,1.5,4), rather than making
            // the result depend on a one-pixel player aim difference.  This is a
            // presentation-only certificate frame; ordinary play still starts at
            // the authoritative terrain ray hit below.
            constexpr float centerX=-5.5f,centerY=-8.75f,centerZ=-17.f;
            constexpr float fy=.9363291775690445f;
            constexpr float fz=-.3511234415883917f;
            float depth=43.f,contactY=0.f,contactZ=0.f;
            for(int i=0;i<12;++i)
            {
                contactY=centerY-fy*depth;
                contactZ=(float)g.causalFaultRuntime->ReconstructedZ(centerX,contactY);
                depth=(centerZ-contactZ)/fz;
            }
            contactY=centerY-fy*depth;
            contactZ=(float)g.causalFaultRuntime->ReconstructedZ(centerX,contactY);
            if ( !GetCell( (int)std::floor(centerX),
                    (int)std::floor(contactY) ) ) { return false; }
            out.px=centerX;out.py=contactY;out.pz=contactZ;
            out.fx=0.f;out.fy=fy;out.fz=fz;
            out.rx=-1.f;out.ry=0.f;out.rz=0.f;
            out.ux=0.f;out.uy=-fz;out.uz=fy;
            g.stage0GeologyInspectorDepthM=depth;
            return true;
        }
        if ( !g.aimHit ) { return false; }
        if ( !GetCell( (int)std::floor( g.aimX ), (int)std::floor( g.aimY ) ) )
        { return false; }
        float cp=std::cos(g.pitch), sp=std::sin(g.pitch);
        float cy=std::cos(g.yaw), sy=std::sin(g.yaw);
        out.px=g.aimX;out.py=g.aimY;out.pz=g.aimZ;
        out.fx=sy*cp;out.fy=cy*cp;out.fz=sp;
        float fl=std::sqrt(out.fx*out.fx+out.fy*out.fy+out.fz*out.fz);
        if(fl<1e-5f){return false;}out.fx/=fl;out.fy/=fl;out.fz/=fl;
        // R = cross(N,F), with a stable fallback for a near-normal view.
        out.rx=g.aimNy*out.fz-g.aimNz*out.fy;
        out.ry=g.aimNz*out.fx-g.aimNx*out.fz;
        out.rz=g.aimNx*out.fy-g.aimNy*out.fx;
        float rl=std::sqrt(out.rx*out.rx+out.ry*out.ry+out.rz*out.rz);
        if(rl<1e-4f){out.rx=1.f;out.ry=out.rz=0.f;rl=1.f;}
        out.rx/=rl;out.ry/=rl;out.rz/=rl;
        out.ux=out.fy*out.rz-out.fz*out.ry;
        out.uy=out.fz*out.rx-out.fx*out.rz;
        out.uz=out.fx*out.ry-out.fy*out.rx;
        float ul=std::sqrt(out.ux*out.ux+out.uy*out.uy+out.uz*out.uz);
        if(ul<1e-5f){return false;}out.ux/=ul;out.uy/=ul;out.uz/=ul;
        // Keep U consistently oriented to the hit normal so panning does not flip
        // the flashlight image between adjacent surface triangles.
        float const un=out.ux*g.aimNx+out.uy*g.aimNy+out.uz*g.aimNz;
        if(un<0.f){out.ux=-out.ux;out.uy=-out.uy;out.uz=-out.uz;
            out.rx=-out.rx;out.ry=-out.ry;out.rz=-out.rz;}
        return true;
    }

    void Stage0InspectorPoint( Stage0InspectorFrame const& f,float d,float r,float u,
        float& x,float& y,float& z )
    {
        x=f.px+f.fx*d+f.rx*r+f.ux*u;
        y=f.py+f.fy*d+f.ry*r+f.uy*u;
        z=f.pz+f.fz*d+f.rz*r+f.uz*u;
    }

    void Stage0InspectorColor( CausalWorldGeology::GeoSample const& geology )
    {
        float r=.45f,green=.32f,b=.20f;
        if(g.stage0GeologyInspectorMode==1)
        {
            uint64_t h=geology.featureId*0x9e3779b97f4a7c15ULL;
            r=.25f+.70f*(float)((h>>8)&255)/255.f;
            green=.25f+.70f*(float)((h>>24)&255)/255.f;
            b=.25f+.70f*(float)((h>>40)&255)/255.f;
        }
        else if(g.stage0GeologyInspectorMode==2)
        {
            uint32_t const age=geology.chronology.empty()?0u:geology.chronology.back();
            float const t=(float)(age%17u)/16.f;
            r=.30f+.65f*t;green=.72f-.42f*t;b=.90f-.55f*t;
        }
        else
        {
            if(geology.material=="sandstone"){r=.68f;green=.49f;b=.29f;}
            else if(geology.material=="shale"){r=.20f;green=.23f;b=.25f;}
            else if(geology.material=="granite"){r=.56f;green=.55f;b=.52f;}
            else if(geology.material=="quartz"){r=.90f;green=.82f;b=.45f;}
        }
        glColor3f(r,green,b);
    }

    void DrawStage0GeologyInspectorMask()
    {
        Stage0InspectorFrame f{};if(!Stage0GeologyInspectorFrame(f)){return;}
        float const half=.5f*g.stage0GeologyInspectorWidthM;
        float const depth=g.stage0GeologyInspectorDepthM;
        float p[8][3];int i=0;
        for(int d=0;d<2;++d)for(int u=0;u<2;++u)for(int r=0;r<2;++r)
        {
            Stage0InspectorPoint(f,d?depth:.025f,r?half:-half,u?half:-half,
                p[i][0],p[i][1],p[i][2]);
            ++i;
        }
        glStencilMask(0xff);glClear(GL_STENCIL_BUFFER_BIT);glEnable(GL_STENCIL_TEST);
        glStencilFunc(GL_ALWAYS,1,0xff);glStencilOp(GL_REPLACE,GL_REPLACE,GL_REPLACE);
        glColorMask(GL_FALSE,GL_FALSE,GL_FALSE,GL_FALSE);glDisable(GL_DEPTH_TEST);
        static int const q[6][4]={{0,1,3,2},{4,6,7,5},{0,4,5,1},{2,3,7,6},{0,2,6,4},{1,5,7,3}};
        glDisable(GL_CULL_FACE);glBegin(GL_QUADS);
        for(auto const& face:q)for(int v:face)glVertex3fv(p[v]);
        glEnd();glEnable(GL_CULL_FACE);glEnable(GL_DEPTH_TEST);
        glColorMask(GL_TRUE,GL_TRUE,GL_TRUE,GL_TRUE);glStencilMask(0x00);
        glStencilFunc(GL_NOTEQUAL,1,0xff);glStencilOp(GL_KEEP,GL_KEEP,GL_KEEP);
    }

    void DrawStage0GeologyCutaway()
    {
        Stage0InspectorFrame f{};if(!Stage0GeologyInspectorFrame(f)){return;}
        constexpr float step=.5f;float const half=.5f*g.stage0GeologyInspectorWidthM;
        float const depth=g.stage0GeologyInspectorDepthM;
        glDisable(GL_STENCIL_TEST);glDisable(GL_CULL_FACE);glBegin(GL_TRIANGLES);
        auto tile=[&](float d0,float d1,float r0,float r1,float u0,float u1,bool terminal)
        {
            float cx,cy,cz;
            Stage0InspectorPoint(f,(d0+d1)*.5f,(r0+r1)*.5f,(u0+u1)*.5f,cx,cy,cz);
            if(!GetCell((int)std::floor(cx),(int)std::floor(cy))){return;}
            auto const geology=CausalGeologyAt(g.stage0PlayView,cx,cy,cz);
            if(!geology.found){return;}Stage0InspectorColor(geology);
            float p0[3],p1[3],p2[3],p3[3];
            if(terminal)
            {
                Stage0InspectorPoint(f,d0,r0,u0,p0[0],p0[1],p0[2]);
                Stage0InspectorPoint(f,d0,r1,u0,p1[0],p1[1],p1[2]);
                Stage0InspectorPoint(f,d0,r1,u1,p2[0],p2[1],p2[2]);
                Stage0InspectorPoint(f,d0,r0,u1,p3[0],p3[1],p3[2]);
            }
            else
            {
                Stage0InspectorPoint(f,d0,r0,u0,p0[0],p0[1],p0[2]);
                Stage0InspectorPoint(f,d1,r0,u0,p1[0],p1[1],p1[2]);
                Stage0InspectorPoint(f,d1,r0,u1,p2[0],p2[1],p2[2]);
                Stage0InspectorPoint(f,d0,r0,u1,p3[0],p3[1],p3[2]);
            }
            glVertex3fv(p0);glVertex3fv(p1);glVertex3fv(p2);
            glVertex3fv(p0);glVertex3fv(p2);glVertex3fv(p3);
        };
        for(float r=-half;r<half-.001f;r+=step)for(float u=-half;u<half-.001f;u+=step)
            tile(depth,depth,r,(std::min)(half,r+step),u,(std::min)(half,u+step),true);
        glEnd();glEnable(GL_CULL_FACE);
    }

    void DrawStage16DryHydrologyDiagnostics()
    {
        CausalDryHydrology::Kernel const* kernel=nullptr;
        CausalCompiledFluvialErosion::Kernel const* fluvial=nullptr;
        CausalCompiledSediment::Kernel const* sediment=nullptr;
        CausalPresentWater::Kernel const* water=nullptr;
        if(UsesPresentWaterOccupancy(g.stage0PlayView)&&ActivePresentWaterKernel())
        {water=ActivePresentWaterKernel();sediment=&water->Sediment();fluvial=&sediment->Erosion();kernel=&sediment->Drainage();}
        else if(IsCompiledSedimentView(g.stage0PlayView)&&g.compiledSedimentRuntime)
        {sediment=g.compiledSedimentRuntime.get();fluvial=&sediment->Erosion();kernel=&sediment->Drainage();}
        else if(IsCompiledFluvialErosionView(g.stage0PlayView)&&g.compiledFluvialRuntime)
        {fluvial=g.compiledFluvialRuntime.get();kernel=&fluvial->Drainage();}
        else if(IsDryHydrologyView(g.stage0PlayView)&&g.dryHydrologyRuntime)
        {kernel=g.dryHydrologyRuntime.get();}
        if(!kernel)return;double const step=kernel->StepM();
        int const radiusCells=(int)std::ceil(96.0/step);
        int const cx=(int)std::floor((g.feetX-kernel->MinX())/step);
        int const cy=(int)std::floor((g.feetY-kernel->MinY())/step);
        GLboolean const lightingWasEnabled=glIsEnabled(GL_LIGHTING);
        GLboolean const textureWasEnabled=glIsEnabled(GL_TEXTURE_2D);
        glDisable(GL_LIGHTING);glDisable(GL_TEXTURE_2D);glLineWidth(2.0f);
        glBegin(GL_LINES);
        for(int oy=-radiusCells;oy<=radiusCells;++oy)
        for(int ox=-radiusCells;ox<=radiusCells;++ox)
        {
            double const qx=kernel->MinX()+(cx+ox+.5)*step;
            double const qy=kernel->MinY()+(cy+oy+.5)*step;
            auto const q=kernel->QueryAt(qx,qy);if(!q.found||q.cell.receiver<0)continue;
            auto const& r=kernel->Cells()[(size_t)q.cell.receiver];
            double const incision=fluvial?fluvial->Cells()[(size_t)q.index].incisionM:0.0;
            double const deposit=sediment?sediment->Cells()[(size_t)q.index].depositDepthM:0.0;
            if(sediment&&deposit>0.01)
            {
                float const normalized=(float)std::clamp(deposit/2.0,0.0,1.0);
                // Amber/sand — never green; cardinal fallback detects green pixels.
                glColor3f(.92f,.72f-.18f*normalized,.18f+.10f*normalized);
            }
            else if(fluvial&&incision>0)
            {
                float const normalized=(float)std::clamp(incision/6.0,0.0,1.0);
                glColor3f(1.0f,.62f-.42f*normalized,.04f);
            }
            else if(q.cell.channel)
            {
                float const order=(float)q.cell.channelOrder;
                glColor3f(1.0f,.72f-(std::min)(order,4.f)*.08f,.05f);
            }
            else glColor3f(.78f,.76f,.62f);
            float const z=(float)(sediment?sediment->Cells()[(size_t)q.index].surfaceZ
                :(fluvial?fluvial->Cells()[(size_t)q.index].surfaceZ
                :q.cell.surfaceZ))+.18f;
            float const rz=(float)(fluvial?fluvial->Cells()[(size_t)q.cell.receiver].surfaceZ
                :r.surfaceZ)+.18f;
            glVertex3f((float)q.cell.x,(float)q.cell.y,z);
            glVertex3f((float)(q.cell.x+.72*(r.x-q.cell.x)),
                (float)(q.cell.y+.72*(r.y-q.cell.y)),(float)(z+.72*(rz-z)));
            // Two short arrow wings make direction readable without rendering
            // a river ribbon or implying present water.
            double const ax=q.cell.x+.72*(r.x-q.cell.x),ay=q.cell.y+.72*(r.y-q.cell.y);
            double const px=-q.flowDy*2.0,py=q.flowDx*2.0;
            glVertex3f((float)ax,(float)ay,(float)(z+.72*(rz-z)));
            glVertex3f((float)(ax-2.5*q.flowDx+px),(float)(ay-2.5*q.flowDy+py),(float)(z+.72*(rz-z)));
            glVertex3f((float)ax,(float)ay,(float)(z+.72*(rz-z)));
            glVertex3f((float)(ax-2.5*q.flowDx-px),(float)(ay-2.5*q.flowDy-py),(float)(z+.72*(rz-z)));
            if(q.cell.spill)
            {
                glColor3f(1.0f,.15f,.65f);
                glVertex3f((float)q.cell.x-3.f,(float)q.cell.y,z+.12f);
                glVertex3f((float)q.cell.x+3.f,(float)q.cell.y,z+.12f);
                glVertex3f((float)q.cell.x,(float)q.cell.y-3.f,z+.12f);
                glVertex3f((float)q.cell.x,(float)q.cell.y+3.f,z+.12f);
            }
        }
        glEnd();glLineWidth(1.0f);
        if(water&&!g.certWorldgenCardinalReplacement)
        {
            // Static present-water surface quads (blue/cyan — never green).
            // Skip during cardinal replacement so 16D presentation cost cannot
            // burn the movement-frame floor.
            glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);
            glBegin(GL_QUADS);
            float const half=(float)(step*.46);
            for(int oy=-radiusCells;oy<=radiusCells;++oy)
            for(int ox=-radiusCells;ox<=radiusCells;++ox)
            {
                double const qx=kernel->MinX()+(cx+ox+.5)*step;
                double const qy=kernel->MinY()+(cy+oy+.5)*step;
                auto const q=water->QueryAt(qx,qy);if(!q.found||!q.occupied)continue;
                float a=.42f;
                if(q.water.kind==CausalPresentWater::BodyKind::Lake)glColor4f(.10f,.34f,.72f,a);
                else if(q.water.kind==CausalPresentWater::BodyKind::River)glColor4f(.08f,.48f,.78f,a);
                else if(q.water.kind==CausalPresentWater::BodyKind::Wetland)glColor4f(.18f,.52f,.58f,a);
                else glColor4f(.12f,.40f,.70f,a);
                float const z=(float)q.waterSurfaceZ+.04f;
                float const x=(float)q.water.x,y=(float)q.water.y;
                glVertex3f(x-half,y-half,z);glVertex3f(x+half,y-half,z);
                glVertex3f(x+half,y+half,z);glVertex3f(x-half,y+half,z);
            }
            glEnd();glDisable(GL_BLEND);
        }
        if(lightingWasEnabled)glEnable(GL_LIGHTING);else glDisable(GL_LIGHTING);
        if(textureWasEnabled)glEnable(GL_TEXTURE_2D);else glDisable(GL_TEXTURE_2D);
    }

    void DrawHeightfield()
    {
        if ( g.certWorldgenBaselinePerf || g.playWorldgenBaseline )
        {
            bool const cutaway = g.playWorldgenBaseline && g.stage0ToolGeologyCutaway
                && IsCausalPlayableView( g.stage0PlayView );
            if ( cutaway ) { DrawStage0GeologyInspectorMask(); }
            // The 64 m disk owns live residency and collision. A coarse latent
            // descriptor reading extends presentation beyond it so the residency
            // boundary is never exposed as sky from free-fly or distant views.
            DrawStage0FarField();
            if ( ( g.playWorldgenBaseline || g.certWorldgenLadderAudit
              || g.certWorldgenLadderLivePerf )
              && ( g.stage0PlayView==Stage0PlayView::Clean
                || IsCausalGeologyView( g.stage0PlayView )
                || IsCausalExposureView( g.stage0PlayView ) ) )
            { DrawStage8TerrainBlocks(); }
            else if ( ( g.playWorldgenBaseline || g.certWorldgenLadderAudit
              || g.certWorldgenLadderLivePerf )
              && ( IsGraniteIntrusionView( g.stage0PlayView )
              || IsContactMineralizationView( g.stage0PlayView )
              || IsFaultDisplacementView( g.stage0PlayView )
              || IsSurfaceBreachView( g.stage0PlayView )
              || UsesExactLocalMaterialization( g.stage0PlayView )
              || UsesBareEarthTerrain( g.stage0PlayView )
              || IsCutCOccupancyView( g.stage0PlayView ) ) )
            { DrawStage8TerrainBlocks(); }
            else if ( ( g.playWorldgenBaseline || g.certStage8Perf || g.certWorldgenLadderAudit
              || g.certWorldgenLadderLivePerf )
              && IsDifferentialErosionView( g.stage0PlayView ) )
            { DrawStage8TerrainBlocks(); }
            else if ( ( g.playWorldgenBaseline || g.certStage8Perf || g.certWorldgenLadderAudit
              || g.certWorldgenLadderLivePerf )
              && IsVisibleExposureView( g.stage0PlayView ) )
            { DrawStage8TerrainBlocks(); }
            else
            { DrawStage0TerrainBlocks(); }
            DrawStage16DryHydrologyDiagnostics();
            if ( cutaway )
            {
                glDisable( GL_STENCIL_TEST );
                DrawStage0GeologyCutaway();
            }
            if ( g.provRenderWorkbench )
            {
                // This early return is why the ore gallery was invisible: the
                // samples were spawned and reseated, but the Stage-0 terrain path
                // exits here, long before DrawMaterialFormGallery further down. The
                // gallery and the E-held sample are part of the workbench, so draw
                // them before leaving.
                DrawMaterialFormGallery();
                DrawHeldGallerySample();
            }
            return;
        }
        int const ax = (int)std::floor( g.feetX );
        int const ay = (int)std::floor( g.feetY );
        // --cert-geo / --cert-residency / --cert-stress: freeze 8-cell vista recenters so remesh=0 is measurable.
        // Play path still recenters for streaming LOD.
        bool const freezeVistaRecenter =
            ( g.certGeo && g.certGeoPhase == 1 && g.certGeoDigArmed == 1 )
         || ( g.certResidency && g.certResidencyPhase >= 2 && g.certResidencyPhase <= 5 )
         || ( g.certStress && g.certStressPhase >= 2 && g.certStressPhase <= 8 );
        if ( !freezeVistaRecenter
          && ( std::abs( ax - g.terrainAnchorX ) >= 8 || std::abs( ay - g.terrainAnchorY ) >= 8 ) )
        {
            InvalidateTerrainMesh( "vista_recenter" );
        }

        if ( g.terrainDirty || !g.terrainList )
        {
            g.terrainAnchorX = ax;
            g.terrainAnchorY = ay;
            RebuildTerrainMesh();
        }

        // Terrain → depth-tested stencil → mouth ALWAYS in punched pixels → interior LEQUAL.
        // Depth-OFF stencil x-rayed through hills. Depth-ON + LEQUAL mouth left HF skin.
        // Punch bias wins vs coplanar HF; nearer hills still win depth by metres.
        if ( g.terrainList ) { glCallList( g.terrainList ); }

        if ( g.certWorldgenBaselinePerf || g.playWorldgenBaseline )
        {
            // Stage-0 is the current HF packaging around one lightweight floor only.
            // Exclude galleries, interaction stencils, cavities, bodies, and support queries.
            return;
        }

        glClear( GL_STENCIL_BUFFER_BIT );
        glEnable( GL_STENCIL_TEST );
        glStencilMask( 0xFF );
        glStencilFunc( GL_ALWAYS, 1, 0xFF );
        glStencilOp( GL_KEEP, GL_KEEP, GL_REPLACE ); // stencil only if punch passes depth
        glColorMask( GL_FALSE, GL_FALSE, GL_FALSE, GL_FALSE );
        glDepthMask( GL_FALSE );
        glEnable( GL_DEPTH_TEST );
        glDepthFunc( GL_LEQUAL );
        glEnable( GL_POLYGON_OFFSET_FILL );
        glPolygonOffset( -3.f, -6.f ); // beat HF z-fight; not enough to leap a nearer hill
        DrawDigGradeFootprints();
        DrawCarveActionFootprints();
        glDisable( GL_POLYGON_OFFSET_FILL );
        glDepthMask( GL_TRUE );

        glStencilFunc( GL_EQUAL, 1, 0xFF );
        glStencilMask( 0x00 );
        glColorMask( GL_TRUE, GL_TRUE, GL_TRUE, GL_TRUE );
        // Reset depth only inside the view-tested replacement stamp, then restore
        // ordinary nearest-surface ordering.  GL_ALWAYS for the actual cavity made
        // rear layers overwrite front layers after enough progressive strikes.
        glColorMask( GL_FALSE, GL_FALSE, GL_FALSE, GL_FALSE );
        glDepthMask( GL_TRUE );
        glDepthRange( 1.0, 1.0 );
        glDepthFunc( GL_ALWAYS );
        DrawDigGradeFootprints();
        DrawCarveActionFootprints();
        glDepthRange( 0.0, 1.0 );
        glColorMask( GL_TRUE, GL_TRUE, GL_TRUE, GL_TRUE );
        glDepthFunc( GL_LESS );
        // The tool-scale boolean patch owns pick replacement pixels.  Do not cover a
        // missing surface with a generated floor plug: a geometric gap must remain a FAIL.
        DrawDigFloorPlugs();
        DrawLiveScoopCups( true );
        DrawCavityMeshesMouth();

        glStencilMask( 0xFF );
        glDisable( GL_STENCIL_TEST );
        glDepthFunc( GL_LEQUAL );
        // The footprint stencil owns removal of the virgin height field, but it is
        // only a 2-D projection. Draw the reconstructed boundary once more with
        // ordinary depth testing so exposed vertical walls and floor pixels outside
        // that projection remain visible without overwriting nearer terrain.
        DrawFractureSurfacePatches();
        DrawCavityMeshesInterior();
        DrawMaterialFormGallery(); // hand-scale material forms east of spawn
        DrawHeldGallerySample();   // E-held sample at hand for close inspect
        DrawLiveScoopCups( false );
        DrawFoliationPlateNotches(); // flash only when carve missed
        DrawFacePunctures();
        DrawMatterBodies();
        glDepthFunc( GL_LESS );
    }

    void DrawMatterBodies()
    {
        // Explicit H2H plates — conserved geometry, not scoop cups / not inventory cubes.
        if ( g.chipMode == ChipMode::Off ) { return; }
        if ( H2H::State().bodies.empty() ) { return; }
        glShadeModel( GL_FLAT );
        glDisable( GL_CULL_FACE );
        glBegin( GL_TRIANGLES );
        for ( H2H::MatterBody const& b : H2H::State().bodies )
        {
            if ( b.gripped ) { continue; } // carried body drawn at hand below
            float const ha = b.alongM * 0.5f;
            float const hc = b.acrossM * 0.5f;
            float const ht = b.thickM * 0.5f;
            float nx = b.nx, ny = b.ny, nz = b.nz;
            float nlen = std::sqrt( nx * nx + ny * ny + nz * nz );
            if ( nlen > 1e-5f ) { nx /= nlen; ny /= nlen; nz /= nlen; }
            else { nx = 0.f; ny = 0.f; nz = 1.f; }
            // Orthonormal tangent frame on the plate (works on vertical walls).
            float sx = b.strikeX, sy = b.strikeY, sz = 0.f;
            float sN = sx * nx + sy * ny + sz * nz;
            sx -= nx * sN; sy -= ny * sN; sz -= nz * sN;
            float slen = std::sqrt( sx * sx + sy * sy + sz * sz );
            if ( slen < 1e-4f )
            {
                sx = -ny; sy = nx; sz = 0.f;
                slen = std::sqrt( sx * sx + sy * sy );
            }
            if ( slen > 1e-5f ) { sx /= slen; sy /= slen; sz /= slen; }
            float tx = ny * sz - nz * sy;
            float ty = nz * sx - nx * sz;
            float tz = nx * sy - ny * sx;
            auto corner = [&]( float a, float c, float t, float& ox, float& oy, float& oz )
            {
                ox = b.x + sx * a + tx * c + nx * t;
                oy = b.y + sy * a + ty * c + ny * t;
                oz = b.z + sz * a + tz * c + nz * t;
            };
            float x000, y000, z000, x100, y100, z100, x010, y010, z010, x110, y110, z110;
            float x001, y001, z001, x101, y101, z101, x011, y011, z011, x111, y111, z111;
            corner( -ha, -hc, -ht, x000, y000, z000 );
            corner( +ha, -hc, -ht, x100, y100, z100 );
            corner( -ha, +hc, -ht, x010, y010, z010 );
            corner( +ha, +hc, -ht, x110, y110, z110 );
            corner( -ha, -hc, +ht, x001, y001, z001 );
            corner( +ha, -hc, +ht, x101, y101, z101 );
            corner( -ha, +hc, +ht, x011, y011, z011 );
            corner( +ha, +hc, +ht, x111, y111, z111 );
            float cav = b.settled ? 0.35f : 0.55f;
            // Broad faces (foliation planes) + thin edges.
            EmitPhase3Tri( x001, y001, z001, x101, y101, z101, x011, y011, z011, cav );
            EmitPhase3Tri( x101, y101, z101, x111, y111, z111, x011, y011, z011, cav );
            EmitPhase3Tri( x000, y000, z000, x010, y010, z010, x100, y100, z100, cav + 0.15f );
            EmitPhase3Tri( x100, y100, z100, x010, y010, z010, x110, y110, z110, cav + 0.15f );
            EmitPhase3Tri( x000, y000, z000, x100, y100, z100, x001, y001, z001, 0.7f );
            EmitPhase3Tri( x100, y100, z100, x101, y101, z101, x001, y001, z001, 0.7f );
            EmitPhase3Tri( x010, y010, z010, x011, y011, z011, x110, y110, z110, 0.7f );
            EmitPhase3Tri( x110, y110, z110, x011, y011, z011, x111, y111, z111, 0.7f );
        }
        glEnd();
        // Gripped plate at hand (contact-carry, not socket snap — offset from camera).
        if ( g.grippedBodyId != 0 )
        {
            for ( H2H::MatterBody const& b : H2H::State().bodies )
            {
                if ( b.body_id != g.grippedBodyId ) { continue; }
                float cp = std::cos( g.pitch ), sp = std::sin( g.pitch );
                float cyw = std::cos( g.yaw ), sy = std::sin( g.yaw );
                float fx = sy * cp, fy = cyw * cp, fz = sp;
                float hx = g.camX + fx * 0.55f + cyw * 0.22f;
                float hy = g.camY + fy * 0.55f - sy * 0.22f;
                float hz = g.camZ + fz * 0.55f - 0.15f;
                H2H::MatterBody draw = b;
                draw.x = hx; draw.y = hy; draw.z = hz;
                draw.gripped = false;
                // Re-enter single-body draw via temporary push (simple: wire box).
                glLineWidth( 2.f );
                glColor3f( 0.85f, 0.88f, 0.70f );
                float const ha = draw.alongM * 0.5f, hc = draw.acrossM * 0.5f, ht = draw.thickM * 0.5f;
                glBegin( GL_LINE_LOOP );
                glVertex3f( hx - ha, hy - hc, hz + ht );
                glVertex3f( hx + ha, hy - hc, hz + ht );
                glVertex3f( hx + ha, hy + hc, hz + ht );
                glVertex3f( hx - ha, hy + hc, hz + ht );
                glEnd();
                glBegin( GL_LINE_LOOP );
                glVertex3f( hx - ha, hy - hc, hz - ht );
                glVertex3f( hx + ha, hy - hc, hz - ht );
                glVertex3f( hx + ha, hy + hc, hz - ht );
                glVertex3f( hx - ha, hy + hc, hz - ht );
                glEnd();
                glLineWidth( 1.f );
                break;
            }
        }
        glEnable( GL_CULL_FACE );
    }

    void DrawScaleReference()
    {
        // Quiet 6ft marker — muted so it is never read as the dig/pick volume sphere.
        float cy = std::cos( g.yaw ), sy = std::sin( g.yaw );
        float fx = sy, fy = cy;
        float rx = cy, ry = -sy;
        float bx = g.feetX + fx * 5.5f + rx * 2.2f;
        float by = g.feetY + fy * 5.5f + ry * 2.2f;
        float gz = g.feetZ;
        SampleGroundZ( bx, by, gz );

        float const h = kCharHeightM;
        float const rad = kCapsuleRadiusM * 0.65f;
        glDisable( GL_CULL_FACE );
        glColor3f( 0.35f, 0.38f, 0.42f );
        glLineWidth( 1.f );
        // vertical body (line strip cylinder proxy)
        glBegin( GL_LINES );
        glVertex3f( bx, by, gz );
        glVertex3f( bx, by, gz + h );
        // height ticks every 1 ft (~0.3048 m)
        for ( int i = 1; i <= 6; ++i )
        {
            float z = gz + (float)i * 0.3048f;
            glVertex3f( bx - rad, by, z );
            glVertex3f( bx + rad, by, z );
        }
        // head ring
        for ( int i = 0; i < 12; ++i )
        {
            float a0 = (float)i / 12.f * 6.2831853f;
            float a1 = (float)( i + 1 ) / 12.f * 6.2831853f;
            glVertex3f( bx + std::cos( a0 ) * rad, by + std::sin( a0 ) * rad, gz + h );
            glVertex3f( bx + std::cos( a1 ) * rad, by + std::sin( a1 ) * rad, gz + h );
        }
        // foot ring
        for ( int i = 0; i < 12; ++i )
        {
            float a0 = (float)i / 12.f * 6.2831853f;
            float a1 = (float)( i + 1 ) / 12.f * 6.2831853f;
            glVertex3f( bx + std::cos( a0 ) * rad, by + std::sin( a0 ) * rad, gz + 0.02f );
            glVertex3f( bx + std::cos( a1 ) * rad, by + std::sin( a1 ) * rad, gz + 0.02f );
        }
        glEnd();
        glEnable( GL_CULL_FACE );
    }

    void SampleAimNormal( float x, float y, float& nx, float& ny, float& nz )
    {
        // Heightfield normal at the click — cue rings lie in this plane (Unreal ImpactNormal).
        constexpr float e = 0.08f;
        float zxm = 0.f, zxp = 0.f, zym = 0.f, zyp = 0.f, zc = 0.f;
        if ( !SampleAimSurfaceZ( x, y, zc ) ) { nx = 0.f; ny = 0.f; nz = 1.f; return; }
        if ( !SampleAimSurfaceZ( x - e, y, zxm ) ) { zxm = zc; }
        if ( !SampleAimSurfaceZ( x + e, y, zxp ) ) { zxp = zc; }
        if ( !SampleAimSurfaceZ( x, y - e, zym ) ) { zym = zc; }
        if ( !SampleAimSurfaceZ( x, y + e, zyp ) ) { zyp = zc; }
        nx = -( zxp - zxm ) / ( 2.f * e );
        ny = -( zyp - zym ) / ( 2.f * e );
        nz = 1.f;
        float const len = std::sqrt( nx * nx + ny * ny + nz * nz );
        if ( len > 1e-6f ) { nx /= len; ny /= len; nz /= len; }
        else { nx = 0.f; ny = 0.f; nz = 1.f; }
    }

    void BasisFromNormal( float nx, float ny, float nz,
                          float& tx, float& ty, float& tz,
                          float& bx, float& by, float& bz )
    {
        // Twin of Unreal FindBestAxisVectors — orthonormal tangent frame on the hit plane.
        float ax = 1.f, ay = 0.f, az = 0.f;
        if ( std::fabs( nx ) > 0.9f ) { ax = 0.f; ay = 1.f; az = 0.f; }
        tx = ay * nz - az * ny;
        ty = az * nx - ax * nz;
        tz = ax * ny - ay * nx;
        float tl = std::sqrt( tx * tx + ty * ty + tz * tz );
        if ( tl > 1e-6f ) { tx /= tl; ty /= tl; tz /= tl; }
        else { tx = 0.f; ty = 1.f; tz = 0.f; }
        bx = ny * tz - nz * ty;
        by = nz * tx - nx * tz;
        bz = nx * ty - ny * tx;
    }

    void FireActionCue( bool place, bool busy )
    {
        if ( !g.aimHit ) { return; }
        g.cueT = busy ? 0.22f : 0.20f;
        g.cueX = g.aimX;
        g.cueY = g.aimY;
        g.cueZ = g.aimZ;
        SampleAimNormal( g.aimX, g.aimY, g.cueNx, g.cueNy, g.cueNz );
        g.cuePlace = place;
        g.cueBusy = busy;
    }

    void DrawSurfaceRing( float ox, float oy, float oz,
                          float tx, float ty, float tz,
                          float bx, float by, float bz,
                          float radius, float cr, float cg, float cb, int seg )
    {
        glColor3f( cr, cg, cb );
        glBegin( GL_LINE_LOOP );
        for ( int i = 0; i < seg; ++i )
        {
            float const a = (float)i / (float)seg * 6.2831853f;
            float const ca = std::cos( a ), sa = std::sin( a );
            glVertex3f( ox + ( tx * ca + bx * sa ) * radius,
                        oy + ( ty * ca + by * sa ) * radius,
                        oz + ( tz * ca + bz * sa ) * radius );
        }
        glEnd();
    }

    void DrawHorizontalRing( float cx, float cy, float cz, float radius, float cr, float cg, float cb, int seg )
    {
        DrawSurfaceRing( cx, cy, cz, 1.f, 0.f, 0.f, 0.f, 1.f, 0.f, radius, cr, cg, cb, seg );
    }

    void DrawActionCue( float dt )
    {
        // Twin of Unreal FsDrawImmediateTerrainCue: rings in the hit tangent plane + radial dashes.
        if ( g.cueT <= 0.f ) { return; }
        g.cueT = (std::max)( 0.f, g.cueT - dt );
        float const life = g.cueBusy ? 0.22f : 0.20f;
        float const u = (std::max)( 0.f, g.cueT / life ); // 1 → 0
        float const fade = u * u;
        float cr, cg, cb;
        if ( g.cueBusy ) { cr = 1.f; cg = 0.67f; cb = 0.18f; }
        else if ( g.cuePlace ) { cr = 0.31f; cg = 0.86f; cb = 1.f; }
        else { cr = 0.35f; cg = 1.f; cb = 0.53f; }
        cr *= fade; cg *= fade; cb *= fade;

        float const cueR = AimDigAffect().radiusM;
        float nx = g.cueNx, ny = g.cueNy, nz = g.cueNz;
        float tx, ty, tz, bx, by, bz;
        BasisFromNormal( nx, ny, nz, tx, ty, tz, bx, by, bz );
        // Lift along normal so the splash sits on the clicked face (Unreal: ImpactPoint + N*1.5cm).
        float const lift = 0.015f;
        float const ox = g.cueX + nx * lift;
        float const oy = g.cueY + ny * lift;
        float const oz = g.cueZ + nz * lift;
        float const expand = 1.f + ( 1.f - u ) * 0.35f;

        glDisable( GL_CULL_FACE );
        glLineWidth( 2.2f );
        DrawSurfaceRing( ox, oy, oz, tx, ty, tz, bx, by, bz, cueR * expand, cr, cg, cb, 28 );
        DrawSurfaceRing( ox + nx * 0.005f, oy + ny * 0.005f, oz + nz * 0.005f,
                         tx, ty, tz, bx, by, bz, cueR * 0.52f * expand, cr, cg, cb, 20 );
        DrawWireSphere( ox, oy, oz, 0.012f, fade, fade, fade, 8 );

        // Dig radiates outward; place gathers inward — in the surface plane.
        glBegin( GL_LINES );
        glColor3f( cr, cg, cb );
        for ( int i = 0; i < 6; ++i )
        {
            float const a = ( 6.2831853f * (float)i / 6.f ) + 0.24f;
            float const ca = std::cos( a ), sa = std::sin( a );
            float const dx = tx * ca + bx * sa;
            float const dy = ty * ca + by * sa;
            float const dz = tz * ca + bz * sa;
            float const r0 = cueR * ( g.cuePlace ? 1.18f : 0.68f ) * expand;
            float const r1 = cueR * ( g.cuePlace ? 0.68f : 1.18f ) * expand;
            float const n0 = g.cuePlace ? 0.035f : 0.005f;
            float const n1 = g.cuePlace ? 0.005f : 0.035f;
            glVertex3f( ox + dx * r0 + nx * n0, oy + dy * r0 + ny * n0, oz + dz * r0 + nz * n0 );
            glVertex3f( ox + dx * r1 + nx * n1, oy + dy * r1 + ny * n1, oz + dz * r1 + nz * n1 );
        }
        glEnd();
        glLineWidth( 1.f );
        glEnable( GL_CULL_FACE );
    }

    void DrawAimScoop()
    {
        if ( !g.aimHit ) { return; }
        glDisable( GL_CULL_FACE );
        DigAffectSpec const affect = AimDigAffect();
        float const affectR = affect.radiusM;
        // Dig-volume ONLY — never draw the large contact envelope as a second sphere
        // (players read contact r=0.18–0.28m as the pick/shovel dig volume).
        if ( g.heldTotalG > 0 )
        {
            DrawWireSphere( g.aimX, g.aimY, g.aimZ, affectR, 0.95f, 0.72f, 0.28f, 24 );
        }
        else if ( affect.mode == DigAffectMode::FoliationPlate )
        {
            float fnx = 0.f, fny = 0.f, fnz = 1.f;
            CaptureFaceNormalAt( g.aimX, g.aimY, fnx, fny, fnz );
            float cp = std::cos( g.pitch ), sp = std::sin( g.pitch );
            float cyw = std::cos( g.yaw ), sy = std::sin( g.yaw );
            float fx = sy * cp, fy = cyw * cp, fz = sp;
            float strikeX = 1.f, strikeY = 0.f;
            StrikeAxesFromLook( fnx, fny, fnz, fx, fy, fz, strikeX, strikeY );
            float const along = (std::max)( affectR * 1.8f, RockStruct::kPickOpenAlongM * 0.45f );
            float const across = affectR;
            glLineWidth( 2.f );
            glColor3f( 0.75f, 0.92f, 1.f );
            // Seam ellipse in the FACE plane (not XY flat on grade).
            float t1x = strikeX, t1y = strikeY, t1z = 0.f;
            float t1n = t1x * fnx + t1y * fny + t1z * fnz;
            t1x -= fnx * t1n; t1y -= fny * t1n; t1z -= fnz * t1n;
            float t1len = std::sqrt( t1x * t1x + t1y * t1y + t1z * t1z );
            if ( t1len > 1e-5f ) { t1x /= t1len; t1y /= t1len; t1z /= t1len; }
            float t2x = fny * t1z - fnz * t1y;
            float t2y = fnz * t1x - fnx * t1z;
            float t2z = fnx * t1y - fny * t1x;
            float const lift = 0.008f;
            float const ox = g.aimX + fnx * lift, oy = g.aimY + fny * lift, oz = g.aimZ + fnz * lift;
            glBegin( GL_LINE_LOOP );
            for ( int i = 0; i < 24; ++i )
            {
                float const a = (float)i * 6.2831853f / 24.f;
                float const ca = std::cos( a ), sa = std::sin( a );
                glVertex3f(
                    ox + t1x * ( along * ca ) + t2x * ( across * sa ),
                    oy + t1y * ( along * ca ) + t2y * ( across * sa ),
                    oz + t1z * ( along * ca ) + t2z * ( across * sa ) );
            }
            glEnd();
            DrawWireSphere( ox, oy, oz, affectR, 0.45f, 0.90f, 1.f, 20 );
            glLineWidth( 1.f );
        }
        else
        {
            DrawWireSphere( g.aimX, g.aimY, g.aimZ, affectR, 0.25f, 0.95f, 0.45f, 26 );
        }
        glEnable( GL_CULL_FACE );
    }

    // Heightfield is a sheet: solid is "below grade". Steep cliffs need horizontal capsule tests
    // or the camera walks through the wall (per-frame climb < maxStep skates into the mesh).
    bool CapsuleHitsWall( float x, float y, float feetZ )
    {
        constexpr int kProbes = 12;
        float const r = kCapsuleRadiusM;
        float const bodyTop = feetZ + kEyeHeightM; // refuse walls into the POV
        int const feetCx = (int)std::floor( x );
        int const feetCy = (int)std::floor( y );
        CellSample const* feetCell = GetCell( feetCx, feetCy );
        bool const standingInCarve = feetCell && feetCell->carved && !feetCell->fill.empty();
        float virginUnderFeet = feetZ;
        bool haveVirgin = SampleGroundZBase( x, y, virginUnderFeet );

        for ( int i = 0; i < kProbes; ++i )
        {
            float const a = ( 6.2831853f * (float)i ) / (float)kProbes;
            float const px = x + std::cos( a ) * r;
            float const py = y + std::sin( a ) * r;
            float gz = feetZ;
            if ( !SampleGroundZ( px, py, gz ) ) { continue; }
            // Standing in a cavity: ignore virgin HF sheet beside the aperture as a "wall."
            // Real walls are occupancy-solid at torso/eye height.
            if ( standingInCarve && haveVirgin && feetZ < virginUnderFeet - 0.12f )
            {
                int const pcx = (int)std::floor( px );
                int const pcy = (int)std::floor( py );
                CellSample const* pc = GetCell( pcx, pcy );
                bool const probeCarved = pc && pc->carved && !pc->fill.empty();
                if ( !probeCarved
                    || ( !OccupancySolidAt( px, py, feetZ + 0.9f )
                      && !OccupancySolidAt( px, py, feetZ + 1.55f ) ) )
                {
                    continue;
                }
            }
            // Wall beside feet: grade rises into the body / eyes.
            if ( gz > feetZ + kWallBodyClearM && gz > feetZ + 0.15f )
            {
                return true;
            }
            // Camera buried in cliff sheet.
            if ( gz > bodyTop - 0.12f )
            {
                return true;
            }
        }
        // Center column: eye must stay above support (never inside the sheet).
        float gCenter = feetZ;
        if ( SampleGroundZ( x, y, gCenter ) && gCenter > bodyTop - 0.08f )
        {
            return true;
        }
        return false;
    }

    bool WalkStepAllowed( float fromX, float fromY, float fromZ, float toX, float toY, float& outGroundZ )
    {
        if ( !SampleGroundZ( toX, toY, outGroundZ ) ) { return false; }
        float const climb = outGroundZ - fromZ;
        float const dx = toX - fromX;
        float const dy = toY - fromY;
        float const horiz = std::sqrt( dx * dx + dy * dy );
        // Up only — walking off cliffs is a downward (or airborne) step and must stay allowed.
        if ( climb > kMaxStepM ) { return false; }
        if ( horiz > 1e-5f && climb > 0.f && ( climb / horiz ) > kMaxWalkSlope ) { return false; }

        // Capsule vs walls: test at current height when stepping down / off a ledge.
        // Using the *lower* standZ false-positives against the cliff you just left (blocks run-off).
        float const capsuleZ = ( climb > 0.05f ) ? outGroundZ : fromZ;
        if ( CapsuleHitsWall( toX, toY, capsuleZ ) ) { return false; }
        return true;
    }

    void ResolveEyeInOccupancyAir()
    {
        // Inside carved matter: crouch eye under solid, then push XY if eye still embeds in a wall.
        // Without this, standing eye height punches through the back wall → near-clip void.
        int const cx = (int)std::floor( g.feetX );
        int const cy = (int)std::floor( g.feetY );
        CellSample const* cell = GetCell( cx, cy );
        bool const inCarve = cell && cell->carved && !cell->fill.empty();
        float virginZ = g.feetZ;
        bool const belowVirgin = SampleGroundZBase( g.feetX, g.feetY, virginZ )
            && g.feetZ < virginZ - 0.10f;
        float const desiredEyeHeight=kEyeHeightM
            +(kCrouchEyeHeightM-kEyeHeightM)*g.playerCrouch;
        if ( !inCarve && !belowVirgin )
        {
            g.camX = g.feetX;
            g.camY = g.feetY;
            g.camZ = g.feetZ + desiredEyeHeight;
            g.projNearM = kProjNearDefaultM;
            return;
        }

        g.projNearM = kProjNearCavityM;

        float eyeH = desiredEyeHeight;
        // Shallow/open pits: standing eye floats above the virgin lip (screenshot: feet 3.66, eye 5.36
        // over grade ~4.1). Prefer eyes under the crest when there is headroom in the pocket.
        if ( belowVirgin )
        {
            float const underLip = virginZ - g.feetZ - 0.10f;
            if ( underLip >= kEyeCrouchMinM )
            {
                eyeH = (std::min)( eyeH, underLip );
            }
        }
        auto eyeBlocked = [&]( float h ) -> bool
        {
            float const ez = g.feetZ + h;
            float const mz = g.feetZ + h * 0.55f;
            return OccupancySolidAt( g.feetX, g.feetY, ez )
                || OccupancySolidAt( g.feetX, g.feetY, mz );
        };
        if ( inCarve && eyeBlocked( eyeH ) )
        {
            while ( eyeH > kEyeCrouchMinM && eyeBlocked( eyeH ) )
            {
                eyeH -= 0.05f;
            }
            if ( eyeBlocked( eyeH ) ) { eyeH = kEyeCrouchMinM; }
        }

        g.camX = g.feetX;
        g.camY = g.feetY;
        g.camZ = g.feetZ + eyeH;

        // Lateral push: eye must sit in air, not inside the wall behind the character.
        for ( int iter = 0; iter < 10; ++iter )
        {
            if ( !OccupancySolidAt( g.camX, g.camY, g.camZ )
              && !OccupancySolidAt( g.camX, g.camY, g.feetZ + 0.95f ) )
            {
                break;
            }
            float pushX = 0.f, pushY = 0.f;
            int airN = 0;
            constexpr int kDirs = 12;
            for ( int i = 0; i < kDirs; ++i )
            {
                float const a = ( 6.2831853f * (float)i ) / (float)kDirs;
                float const dx = std::cos( a ), dy = std::sin( a );
                float const px = g.camX + dx * 0.12f;
                float const py = g.camY + dy * 0.12f;
                if ( !OccupancySolidAt( px, py, g.camZ )
                  && !OccupancySolidAt( px, py, g.feetZ + 0.95f ) )
                {
                    pushX += dx; pushY += dy; ++airN;
                }
            }
            if ( airN <= 0 ) { break; }
            float plen = std::sqrt( pushX * pushX + pushY * pushY );
            if ( plen < 1e-5f ) { break; }
            pushX /= plen; pushY /= plen;
            g.feetX += pushX * 0.06f;
            g.feetY += pushY * 0.06f;
            g.camX = g.feetX;
            g.camY = g.feetY;
            float ground = g.feetZ;
            if ( SupportAt( g.feetX, g.feetY, ground ) )
            {
                if ( g.feetZ < ground ) { g.feetZ = ground; }
            }
            g.camZ = g.feetZ + eyeH;
        }
    }

    void ResolveWalkOutOfWall()
    {
        // If already clipped into a cliff, nudge feet toward free space (down-slope / away from high probes).
        for ( int iter = 0; iter < 6; ++iter )
        {
            if ( !CapsuleHitsWall( g.feetX, g.feetY, g.feetZ ) )
            {
                float eyeG = g.feetZ;
                if ( SampleGroundZ( g.feetX, g.feetY, eyeG )
                  && eyeG <= g.feetZ + kEyeHeightM - 0.08f )
                {
                    return;
                }
            }
            float pushX = 0.f, pushY = 0.f;
            constexpr int kProbes = 12;
            for ( int i = 0; i < kProbes; ++i )
            {
                float const a = ( 6.2831853f * (float)i ) / (float)kProbes;
                float const cx = std::cos( a ), cy = std::sin( a );
                float const px = g.feetX + cx * kCapsuleRadiusM;
                float const py = g.feetY + cy * kCapsuleRadiusM;
                float gz = g.feetZ;
                if ( !SampleGroundZ( px, py, gz ) ) { continue; }
                float const pen = gz - ( g.feetZ + kWallBodyClearM );
                if ( pen > 0.f )
                {
                    pushX -= cx * pen;
                    pushY -= cy * pen;
                }
            }
            float eyeG = g.feetZ;
            if ( SampleGroundZ( g.feetX, g.feetY, eyeG ) )
            {
                float const eyePen = eyeG - ( g.feetZ + kEyeHeightM - 0.1f );
                if ( eyePen > 0.f )
                {
                    // Push opposite look-forward horizontal (back out of the face).
                    float const ly = std::cos( g.yaw ), lx = std::sin( g.yaw );
                    pushX -= lx * eyePen;
                    pushY -= ly * eyePen;
                }
            }
            float plen = std::sqrt( pushX * pushX + pushY * pushY );
            if ( plen < 1e-5f ) { break; }
            pushX /= plen; pushY /= plen;
            g.feetX += pushX * 0.08f;
            g.feetY += pushY * 0.08f;
            float ground = g.feetZ;
            if ( SampleGroundZ( g.feetX, g.feetY, ground ) )
            {
                g.feetZ = ground;
                g.velZ = 0.f;
                g.grounded = true;
            }
        }
    }

    void UpdateCamera( float dt )
    {
        // The shelter certificate deliberately leaves the normal simulation alive
        // for a few frames so the rebuilt terrain reaches the back buffer.  Keep
        // that proof camera fixed: free-flight input and collision correction can
        // otherwise move it several metres before the screenshot is read back.
        if ( g.shelterPhotoPending > 0 )
        {
            g.camX=g.shelterPhotoCamX;g.camY=g.shelterPhotoCamY;
            g.camZ=g.shelterPhotoCamZ;g.yaw=g.shelterPhotoYaw;
            g.pitch=g.shelterPhotoPitch;
            g.feetX=g.camX;g.feetY=g.camY;g.feetZ=g.camZ-kEyeHeightM;
            g.walkMode=false;g.grounded=false;
            return;
        }
        if ( g.certPickFracture && g.certPickFracturePhase >= 1 )
        {
            // Deterministic near-vertical progressive-cavity camera. Exact -pi/2
            // degenerates the Z-up look-at basis; -1.568 remains centered in the 4.9 cm bore.
            g.camX=g.certPickVisualX; g.camY=g.certPickVisualY;
            g.camZ=g.certPickVisualZ+1.0f;
            g.feetX=g.camX; g.feetY=g.camY; g.feetZ=g.camZ-kEyeHeightM;
            g.walkMode=false; g.grounded=false; g.yaw=0.f; g.pitch=-1.568f;
            return;
        }
        // F toggles walk / free-fly
        if ( g.keys['F'] && !g.keyToggleLatch['F'] )
        {
            g.walkMode = !g.walkMode;
            g.keyToggleLatch['F'] = true;
            g.flySprintDistanceM = 0.f;
            g.flySprintTier = 0;
            g.flyCurrentSpeedMps = g.walkMode ? 0.f : kFlySpeedMps;
            if ( g.walkMode )
            {
                g.velZ = 0.f;
                float ground = g.feetZ;
                if ( SampleGroundZ( g.feetX, g.feetY, ground ) )
                {
                    g.feetZ = ground;
                    g.grounded = true;
                }
                g.statusLine = "Phase 4 - walk (6ft)";
            }
            else
            {
                g.stage0SlideRemaining=g.stage0SlideSpeed=0.f;
                g.statusLine = "FREE CAMERA — WASD move  Q/Ctrl down  E/Space up  F walk";
            }
            UpdateStreamHud();
        }
        if ( !g.keys['F'] ) { g.keyToggleLatch['F'] = false; }

        float const crouchTarget=(g.playWorldgenBaseline&&g.walkMode&&g.playerCrouched)?1.f:0.f;
        float const crouchStep=dt/0.18f;
        if(g.playerCrouch<crouchTarget)g.playerCrouch=(std::min)(crouchTarget,g.playerCrouch+crouchStep);
        else if(g.playerCrouch>crouchTarget)g.playerCrouch=(std::max)(crouchTarget,g.playerCrouch-crouchStep);

        float cy = std::cos( g.yaw ), sy = std::sin( g.yaw );
        float fx = sy, fy = cy;
        float rx = cy, ry = -sy;

        if ( g.walkMode )
        {
            float const speed = g.playerCrouched ? 2.7f
                : (g.keys[VK_SHIFT] ? kSprintSpeedMps : kWalkSpeedMps);
            float wishX = 0.f, wishY = 0.f;
            if ( g.keys['W'] ) { wishX += fx; wishY += fy; }
            if ( g.keys['S'] ) { wishX -= fx; wishY -= fy; }
            if ( g.keys['A'] ) { wishX -= rx; wishY -= ry; }
            if ( g.keys['D'] ) { wishX += rx; wishY += ry; }
            float wlen = std::sqrt( wishX * wishX + wishY * wishY );
            if ( wlen > 1e-5f )
            {
                wishX = ( wishX / wlen ) * speed * dt;
                wishY = ( wishY / wlen ) * speed * dt;
            }
            bool const sliding=g.stage0SlideRemaining>0.f&&g.stage0SlideSpeed>0.f&&g.grounded;
            if(sliding)
            {
                wishX=g.stage0SlideDirX*g.stage0SlideSpeed*dt;
                wishY=g.stage0SlideDirY*g.stage0SlideSpeed*dt;
                wlen=g.stage0SlideSpeed*dt;
            }

            float const fromX = g.feetX, fromY = g.feetY, fromZ = g.feetZ;
            auto tryMove = [&]( float dx, float dy ) -> bool
            {
                float tx = fromX + dx, ty = fromY + dy, gz = fromZ;
                if ( !WalkStepAllowed( fromX, fromY, fromZ, tx, ty, gz ) ) { return false; }
                g.feetX = tx;
                g.feetY = ty;
                return true;
            };
            if ( wlen > 1e-5f )
            {
                // Full wish, then axis slides along walls.
                if ( !tryMove( wishX, wishY ) )
                {
                    if(sliding)
                    {g.stage0SlideRemaining=0.f;g.stage0SlideSpeed=0.f;}
                    else if ( !tryMove( wishX, 0.f ) )
                    {
                        tryMove( 0.f, wishY );
                    }
                }
            }
            if(sliding)
            {
                g.stage0SlideRemaining=(std::max)(0.f,g.stage0SlideRemaining-dt);
                g.stage0SlideSpeed=(std::max)(0.f,g.stage0SlideSpeed-14.f*dt);
            }

            if ( g.keys[VK_SPACE] && g.grounded )
            {
                g.stage0SlideRemaining=g.stage0SlideSpeed=0.f;
                g.velZ = kJumpSpeedMps;
                g.grounded = false;
            }

            g.velZ -= kGravityMps2 * dt;
            g.feetZ += g.velZ * dt;

            float ground = g.feetZ;
            if ( SampleGroundZ( g.feetX, g.feetY, ground ) )
            {
                if ( g.feetZ <= ground )
                {
                    g.feetZ = ground;
                    g.velZ = 0.f;
                    g.grounded = true;
                }
                else
                {
                    g.grounded = false;
                }
            }
            if(!g.grounded){g.stage0SlideRemaining=g.stage0SlideSpeed=0.f;}

            ResolveWalkOutOfWall();

            // Horizon-to-Hand loose plates — PHYS only; SupportBelow from body Z (not crest).
            if ( g.chipMode == ChipMode::Phys )
            {
                H2H::StepBodies( dt, []( float x, float y, float queryZ ) -> H2H::SupportQuery {
                    SupportHit const h = SupportBelow( x, y, queryZ );
                    H2H::SupportQuery q{};
                    q.hit = h.hit;
                    q.deferred = h.deferred;
                    q.x = h.position.x;
                    q.y = h.position.y;
                    q.z = h.position.z;
                    q.nx = h.normal.x;
                    q.ny = h.normal.y;
                    q.nz = h.normal.z;
                    q.supportRev = h.regionRev;
                    return q;
                } );
            }
            // Carry gripped plate with the hand (contact follow).
            if ( g.grippedBodyId != 0 )
            {
                float cp = std::cos( g.pitch ), sp = std::sin( g.pitch );
                float cyw = std::cos( g.yaw ), sy = std::sin( g.yaw );
                float fx = sy * cp, fy = cyw * cp, fz = sp;
                for ( H2H::MatterBody& b : H2H::State().bodies )
                {
                    if ( b.body_id != g.grippedBodyId ) { continue; }
                    b.x = g.camX + fx * 0.55f + cyw * 0.22f;
                    b.y = g.camY + fy * 0.55f - sy * 0.22f;
                    b.z = g.camZ + fz * 0.55f - 0.15f;
                    b.vx = b.vy = b.vz = 0.f;
                    break;
                }
            }

            // Camera is eyes on the 6ft body — crouch / push clear of occupancy walls in carves.
            ResolveEyeInOccupancyAir();
            // Final POV clamp — never leave the eye inside the heightfield sheet (virgin only).
            {
                float gEye = g.camZ;
                int const ecx = (int)std::floor( g.camX );
                int const ecy = (int)std::floor( g.camY );
                CellSample const* ec = GetCell( ecx, ecy );
                bool const eyeInCarve = ec && ec->carved;
                if ( !eyeInCarve
                  && SampleGroundZBase( g.camX, g.camY, gEye ) && gEye > g.camZ - 0.05f )
                {
                    ResolveWalkOutOfWall();
                    ResolveEyeInOccupancyAir();
                }
            }
            FollowStreamCenter();
            ResolveSolidSampleCollisions();
        }
        else
        {
            // Free-fly (debug / aerial). Ctrl/Q down, E/Space up — no auto terrain stick.
            float wishX = 0.f, wishY = 0.f, wishZ = 0.f;
            if ( g.keys['W'] ) { wishX += fx; wishY += fy; }
            if ( g.keys['S'] ) { wishX -= fx; wishY -= fy; }
            if ( g.keys['A'] ) { wishX -= rx; wishY -= ry; }
            if ( g.keys['D'] ) { wishX += rx; wishY += ry; }
            if ( g.keys['Q'] || g.keys[VK_CONTROL] ) { wishZ -= 1.f; }
            if ( g.keys['E'] || g.keys[VK_SPACE] ) { wishZ += 1.f; }
            float const wishLength = std::sqrt( wishX * wishX + wishY * wishY + wishZ * wishZ );
            bool const sprinting = g.keys[VK_SHIFT] && wishLength > 1e-6f;
            if ( !g.keys[VK_SHIFT] )
            {
                g.flySprintDistanceM = 0.f;
                g.flySprintTier = 0;
            }
            float const speed = sprinting
                ? kFlySprintMps + (float)g.flySprintTier * kFlySprintTierStepMps
                : kFlySpeedMps;
            g.flyCurrentSpeedMps = speed;
            if ( wishLength > 1e-6f )
            {
                float const distance = speed * dt;
                g.camX += wishX / wishLength * distance;
                g.camY += wishY / wishLength * distance;
                g.camZ += wishZ / wishLength * distance;
                if ( sprinting )
                {
                    g.flySprintDistanceM += distance;
                    g.flySprintTier = (int)std::floor(
                        g.flySprintDistanceM / kFlySprintTierDistanceM );
                }
            }
            g.feetX = g.camX;
            g.feetY = g.camY;
            g.feetZ = g.camZ - kEyeHeightM;
            g.grounded = false;
            {
                int const cx = (int)std::floor( g.camX );
                int const cy = (int)std::floor( g.camY );
                CellSample const* cell = GetCell( cx, cy );
                g.projNearM = ( cell && cell->carved ) ? kProjNearCavityM : kProjNearDefaultM;
            }
            FollowStreamCenter();
            // Free-fly is a diagnostic camera, not a body. Collision belongs to
            // walk mode; applying it here made distant aerial traversal feel as
            // though the camera were striking invisible terrain.
        }
    }

    void DrawCompass( float cx, float cy )
    {
        // Easy-read heading: yaw 0 = +Y (North). Clockwise to East (+X).
        float deg = g.yaw * ( 180.f / 3.14159265f );
        while ( deg < 0.f ) { deg += 360.f; }
        while ( deg >= 360.f ) { deg -= 360.f; }
        char const* card = "N";
        if ( deg >= 337.5f || deg < 22.5f ) { card = "N"; }
        else if ( deg < 67.5f ) { card = "NE"; }
        else if ( deg < 112.5f ) { card = "E"; }
        else if ( deg < 157.5f ) { card = "SE"; }
        else if ( deg < 202.5f ) { card = "S"; }
        else if ( deg < 247.5f ) { card = "SW"; }
        else if ( deg < 292.5f ) { card = "W"; }
        else { card = "NW"; }

        float const R = 36.f;
        glColor3f( 0.12f, 0.14f, 0.18f );
        glBegin( GL_TRIANGLE_FAN );
        glVertex2f( cx, cy );
        for ( int i = 0; i <= 24; ++i )
        {
            float a = (float)i / 24.f * 6.2831853f;
            glVertex2f( cx + std::cos( a ) * R, cy + std::sin( a ) * R );
        }
        glEnd();
        glColor3f( 0.85f, 0.88f, 0.92f );
        glBegin( GL_LINE_LOOP );
        for ( int i = 0; i < 32; ++i )
        {
            float a = (float)i / 32.f * 6.2831853f;
            glVertex2f( cx + std::cos( a ) * R, cy + std::sin( a ) * R );
        }
        glEnd();

        // Needle: tip points the way you face (screen-up = look). Fixed N mark at top of dial.
        float rad = g.yaw; // face direction in world; dial keeps N up, needle rotates
        // With N fixed at screen-up, needle angle from +screenY: world yaw measured from +Y,
        // screen needle: rotate by -yaw so when yaw=0 needle points up (N).
        float nx = std::sin( rad );
        float ny = std::cos( rad );
        glColor3f( 0.95f, 0.35f, 0.28f );
        glBegin( GL_TRIANGLES );
        glVertex2f( cx + nx * ( R - 6.f ), cy + ny * ( R - 6.f ) );
        glVertex2f( cx - ny * 5.f - nx * 4.f, cy + nx * 5.f - ny * 4.f );
        glVertex2f( cx + ny * 5.f - nx * 4.f, cy - nx * 5.f - ny * 4.f );
        glEnd();

        glColor3f( 1.f, 1.f, 1.f );
        DrawHudText( cx - 4.f, cy + R + 4.f, "N" );
        DrawHudText( cx + R + 2.f, cy - 6.f, "E" );
        DrawHudText( cx - 4.f, cy - R - 16.f, "S" );
        DrawHudText( cx - R - 14.f, cy - 6.f, "W" );

        char hub[48];
        std::snprintf( hub, sizeof( hub ), "%s  %.0f", card, deg );
        DrawHudText( cx - 28.f, cy - R - 34.f, hub );
    }

    void DrawSessionClock( float x, float y )
    {
        DWORD now = GetTickCount();
        if ( g.sessionStartMs == 0 ) { g.sessionStartMs = now; }
        DWORD elapsed = now - g.sessionStartMs;
        unsigned secs = ( elapsed / 1000u ) % 60u;
        unsigned mins = ( elapsed / 60000u ) % 60u;
        unsigned hours = elapsed / 3600000u;
        char buf[64];
        if ( hours > 0 )
        {
            std::snprintf( buf, sizeof( buf ), "TIME  %u:%02u:%02u", hours, mins, secs );
        }
        else
        {
            std::snprintf( buf, sizeof( buf ), "TIME  %u:%02u", mins, secs );
        }
        glColor3f( 0.95f, 0.97f, 0.75f );
        DrawHudText( x, y, buf );
    }

    void Render()
    {
        if ( !g.glrc ) { return; }
        bool const stage0 = g.certWorldgenBaselinePerf || g.playWorldgenBaseline;
        LARGE_INTEGER render0{}, qpf{};
        if ( stage0 )
        {
            QueryPerformanceFrequency( &qpf );
            QueryPerformanceCounter( &render0 );
        }
        auto stage0Present = [&]()
        {
            LARGE_INTEGER beforePresent{}, afterPresent{};
            QueryPerformanceCounter( &beforePresent );
            double const renderMs = qpf.QuadPart > 0
                ? 1000.0 * (double)( beforePresent.QuadPart - render0.QuadPart )
                    / (double)qpf.QuadPart : 0.0;
            g.stage0FrameDrawSubmitMs =
                (std::max)( 0.0, renderMs - g.stage0FrameHfBuildMs );
            if(Stage0UsesPrePresentCompletion())
            {
                LARGE_INTEGER finish0{},finish1{};
                QueryPerformanceCounter(&finish0);
                glFinish();
                QueryPerformanceCounter(&finish1);
                g.stage0FrameGpuFinishMs=qpf.QuadPart>0
                    ?1000.0*(double)(finish1.QuadPart-finish0.QuadPart)
                        /(double)qpf.QuadPart:0.0;
            }
            SwapBuffers( g.hdc );
            QueryPerformanceCounter( &afterPresent );
            g.stage0FramePresentWaitMs = qpf.QuadPart > 0
                ? 1000.0 * (double)( afterPresent.QuadPart - beforePresent.QuadPart )
                    / (double)qpf.QuadPart : 0.0;
        };

        RECT rc; GetClientRect( g.hwnd, &rc );
        int w = (std::max)( 1, (int)rc.right );
        int h = (std::max)( 1, (int)rc.bottom );
        glViewport( 0, 0, w, h );

        UpdateWorldSun();
        LitSetIdentity();

        // Sky clear (gradient via clear + large back quad)
        glClearColor( 0.45f, 0.62f, 0.88f, 1.f );
        glClear( GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT | GL_STENCIL_BUFFER_BIT );

        glMatrixMode( GL_PROJECTION );
        glLoadIdentity();
        float aspect = (float)w / (float)h;
        // Focal length must reach the projection matrix here, or the capture
        // receipt describes a lens the renderer never used. This line read a
        // hardcoded 60 deg while the receipt reported a swept projection_m11, so
        // an entire focal sweep measured nothing but camera distance.
        float const fovDegrees=(g.certStage0CharacterPortrait&&!g.certStage0CharacterFullBody)
            ?kStage0PortraitFovYDeg:Stage0CaptureFovYDeg();
        float fov = fovDegrees * 3.14159265f / 180.f;
        // Hor+ clamp. The projection is vertical-FOV, so horizontal grows with
        // aspect: a docked viewport at 826x232 (aspect 3.6) reached ~130 degrees
        // horizontally and looked like a fishbowl. Narrow the vertical FOV instead
        // once horizontal would exceed this, which leaves ordinary 16:9 untouched.
        {
            constexpr float kMaxHorizontalFovRad = 100.f * 3.14159265f / 180.f;
            float const horizontal = 2.f * std::atan( std::tan( fov * 0.5f ) * aspect );
            if ( horizontal > kMaxHorizontalFovRad && aspect > 1e-3f )
            {
                fov = 2.f * std::atan( std::tan( kMaxHorizontalFovRad * 0.5f ) / aspect );
            }
        }
        float nearZ = g.projNearM;
        if ( nearZ < 0.03f ) { nearZ = 0.03f; }
        if ( nearZ > 1.f ) { nearZ = 1.f; }
        float farZ = 600.f;
        float f = 1.f / std::tan( fov * 0.5f );
        // Record the projection AS BUILT, not as recomputed elsewhere. A receipt
        // derived independently once described a lens the renderer never used and
        // made an entire focal sweep look valid.
        g.renderedProjM00 = f / aspect;
        g.renderedProjM11 = f;
        g.renderedFovYDeg = fov * 180.f / 3.14159265f;
        float m[16] = {
            f / aspect, 0, 0, 0,
            0, f, 0, 0,
            0, 0, ( farZ + nearZ ) / ( nearZ - farZ ), -1,
            0, 0, ( 2 * farZ * nearZ ) / ( nearZ - farZ ), 0
        };
        glLoadMatrixf( m );

        glMatrixMode( GL_MODELVIEW );
        glLoadIdentity();

        // Camera look
        float cp = std::cos( g.pitch ), sp = std::sin( g.pitch );
        float cy = std::cos( g.yaw ), sy = std::sin( g.yaw );
        float fx = sy * cp, fy = cy * cp, fz = sp;
        // Build look-at manually (eye at cam, target = cam + forward). World Z-up.
        float tx = g.camX + fx, ty = g.camY + fy, tz = g.camZ + fz;
        float upx = 0, upy = 0, upz = 1;
        float zx = g.camX - tx, zy = g.camY - ty, zz = g.camZ - tz;
        float zl = std::sqrt( zx * zx + zy * zy + zz * zz );
        if ( zl > 1e-6f ) { zx /= zl; zy /= zl; zz /= zl; }
        float xx = upy * zz - upz * zy;
        float xy = upz * zx - upx * zz;
        float xz = upx * zy - upy * zx;
        float xl = std::sqrt( xx * xx + xy * xy + xz * xz );
        if ( xl > 1e-6f ) { xx /= xl; xy /= xl; xz /= xl; }
        float yx = zy * xz - zz * xy;
        float yy = zz * xx - zx * xz;
        float yz = zx * xy - zy * xx;
        float mv[16] = {
            xx, yx, zx, 0,
            xy, yy, zy, 0,
            xz, yz, zz, 0,
            -( xx * g.camX + xy * g.camY + xz * g.camZ ),
            -( yx * g.camX + yy * g.camY + yz * g.camZ ),
            -( zx * g.camX + zy * g.camY + zz * g.camZ ),
            1
        };
        glLoadMatrixf( mv );

        // Far backdrop quads (depth off). BOTH use clear-sky blue — never lime/grass-green.
        // Prior ground quad was glColor(0.70,0.80,0.55)=RGB(178,204,140); dig mesh gaps
        // peeked that color and were misread as grass or "lime void." Peek = sky void only.
        glDisable( GL_DEPTH_TEST );
        glBegin( GL_QUADS );
        glColor3f( 0.45f, 0.62f, 0.88f ); // == glClearColor
        float sky = 400.f;
        glVertex3f( g.camX - sky, g.camY - sky, 120.f );
        glVertex3f( g.camX + sky, g.camY - sky, 120.f );
        glVertex3f( g.camX + sky, g.camY + sky, 120.f );
        glVertex3f( g.camX - sky, g.camY + sky, 120.f );
        // The z=-30 "under" quad is what flashed a sky stripe under the dirt during
        // workbench load: the first presents run before the 64 m fixture mesh exists,
        // so the near ground was empty sky. Skip it here; a grade-level dirt fill
        // covers the same gap until far-field tiles arrive.
        if ( !g.provRenderWorkbench )
        {
            glVertex3f( g.camX - sky, g.camY - sky, -30.f );
            glVertex3f( g.camX + sky, g.camY - sky, -30.f );
            glVertex3f( g.camX + sky, g.camY + sky, -30.f );
            glVertex3f( g.camX - sky, g.camY + sky, -30.f );
        }
        glEnd();
        if ( g.provRenderWorkbench && g.stage0FarCoarseTiles.empty() )
        {
            float gz = GradeToZ( g.gradeDatum );
            float const r = 120.f;
            glBegin( GL_QUADS );
            glColor3f( 0.42f, 0.30f, 0.20f );
            glVertex3f( g.camX - r, g.camY - r, gz );
            glVertex3f( g.camX + r, g.camY - r, gz );
            glVertex3f( g.camX + r, g.camY + r, gz );
            glVertex3f( g.camX - r, g.camY + r, gz );
            glEnd();
        }
        glEnable( GL_DEPTH_TEST );

        DrawHeightfield();
        DrawLivingWorldLoadPresentation();
        if(g.certPresentationIsolation&&g.presentationIsolationMode==4)
        {
            stage0Present();
            return;
        }
        if ( g.certWorldgenLadderLivePerf )
        {
            // The live ladder is a deterministic movement driver inside the same
            // visible presentation path as the playable runtime.  Keep the HUD and
            // surface-snapped diagnostics in the measured frame; only input and
            // automatic exit differ from a human play session.
            DrawStage0CalibrationPresentation();
            if ( g.stage0ToolPerformanceHud ) { DrawWorldgenPlayHud( w, h ); }
            DrawWorldgenStageMenu( w, h );
            DrawWorldgenToolDrawer( w, h );
            stage0Present();
            return;
        }
        if ( g.certWorldgenBaselinePerf )
        {
            stage0Present();
            return;
        }
        if ( g.playWorldgenBaseline )
        {
            DrawStage0CalibrationPresentation();
            if ( g.stage0ToolPerformanceHud ) { DrawWorldgenPlayHud( w, h ); }
            DrawWorldgenStageMenu( w, h );
            DrawWorldgenToolDrawer( w, h );
            // The ProvRender workbench is the two worlds merged: the Stage-0
            // palette, character and tool props above, and the Phase-4 interaction
            // layer below -- aim reticle with UV/cell contact, held sample, E
            // pickup, journal and hotbar. Every other worldgen mode still returns
            // here and keeps its bare presentation.
            if ( !g.provRenderWorkbench )
            {
                stage0Present();
                return;
            }
        }
        DrawScaleReference();
        DrawAimScoop();
        DrawActionCue( g.frameDt );

        // HUD orthographic overlay
        glDisable( GL_DEPTH_TEST );
        glDisable( GL_TEXTURE_2D );
        glDisable( GL_STENCIL_TEST );
        glColorMask( GL_TRUE, GL_TRUE, GL_TRUE, GL_TRUE );
        glMatrixMode( GL_PROJECTION );
        glLoadIdentity();
        glOrtho( 0, w, 0, h, -1, 1 );
        glMatrixMode( GL_MODELVIEW );
        glLoadIdentity();
        glColor3f( 0.95f, 0.97f, 1.f );

        char line[256];
        // The diagnostic readout covers the model in a docked viewport, and every
        // fact it reports is already the ProvRender menu's job. F1 hides it while
        // leaving the reticle, hotbar and journal alone.
        bool const showHudText = !g.provRenderWorkbench || g.provRenderHudText;
        if ( showHudText )
        {
        DrawHudText( 16, (float)h - 24, "PROVENANCE" );
        DrawHudText( 16, (float)h - 44, "Phase 4 - Horizon-to-Hand + geography + 6ft walk" );
        {
            char geoLine[512];
            H2H::EnsureReady();
            ProvenanceGeo::EnsureReady();
            auto surf = ProvenanceGeo::SampleSurface(
                (double)g.feetX, (double)g.feetY,
                g.gradeDatum, g.reliefVoxels, g.voxelEdgeM );
            VisualMat::VisualMaterialDef const& vd = VisualMat::OrDirt( surf.cap );
            RockStruct::Foliation const fol = RockStruct::FoliationAt( g.feetX, g.feetY );
            int openN = 0;
            for ( EditedRegion const& er : g.editedRegions ) { openN += (int)er.openings.size(); }
            int fracCells = 0, fracTris = 0;
            for ( FractureSurface::Patch const& p : g.fracturePatches )
            {
                fracCells += p.activeCells;
                fracTris += (int)p.tris.size();
            }
            std::snprintf( geoLine, sizeof( geoLine ),
                "%s | geo %s | fixture=%s | biome=%s | cap=%s form=%s | dip=%.0f° | bodies=%d | editReg=%d opens=%d | frac=%d cells=%d tris=%d | bound=%s d2=%d chips=%s | [B][C][G][F8]",
                H2H::kCapability,
                ProvenanceGeo::kGeneratorId,
                ProvenanceGeo::FixtureName( ProvenanceGeo::Fixture() ),
                ProvenanceGeo::ProvinceName( surf.province ),
                vd.id,
                H2H::FormOrDirt( surf.cap ).material_id,
                fol.dipDeg,
                (int)H2H::State().bodies.size(),
                (int)g.editedRegions.size(),
                openN,
                (int)g.fractureEvents.size(), fracCells, fracTris,
                g.boundaryMode == BoundaryMode::D2 ? "D2"
                    : ( g.boundaryMode == BoundaryMode::DebugBoundary ? "AABB" : "OVER" ),
                g.cavityTrisTotal,
                g.chipMode == ChipMode::Off ? "OFF"
                    : ( g.chipMode == ChipMode::Visual ? "VIS" : "PHYS" ) );
            DrawHudText( 16, (float)h - 56, geoLine );
        }
        // Chip quiescence probe (P3d.1) — id/life/state/speed/nz/z/restZ/|z-rest|/quiet/supportRev
        if ( g.chipMode != ChipMode::Off && !H2H::State().bodies.empty() )
        {
            int shown = 0;
            float chipY = (float)h - 62.f;
            for ( H2H::MatterBody const& b : H2H::State().bodies )
            {
                if ( shown >= 3 ) { break; }
                char probe[256];
                H2H::FormatChipProbe( b, probe, (int)sizeof( probe ) );
                glColor3f( 0.85f, 0.95f, 0.75f );
                DrawHudText( 16, chipY - (float)( shown * 12 ), probe );
                ++shown;
            }
            char actLine[96];
            std::snprintf( actLine, sizeof( actLine ),
                "activeChips=%d sleepQuietN=%d",
                H2H::CountActiveChips(), H2H::kChipSleepQuietFrames );
            glColor3f( 0.75f, 0.90f, 0.70f );
            DrawHudText( 16, chipY - (float)( shown * 12 ), actLine );
            glColor3f( 0.95f, 0.97f, 1.f );
        }
        std::snprintf( line, sizeof( line ), "Link: %s   Engine: %s:%d", LinkLabel( g.link ), g.host.c_str(), g.port );
        DrawHudText( 16, (float)h - 68, line );
        DrawHudText( 16, (float)h - 88, g.statusLine.c_str() );
        DrawSessionClock( 16, (float)h - 108 );

        int yHud = h - 132;
        size_t start = 0;
        while ( start < g.detail.size() && yHud > 56 )
        {
            size_t end = g.detail.find( '\n', start );
            if ( end == std::string::npos ) { end = g.detail.size(); }
            std::string row = g.detail.substr( start, end - start );
            DrawHudText( 16, (float)yHud, row.c_str() );
            yHud -= 18;
            start = end + 1;
        }
        }   // end diagnostic readout

        // The crosshair and the aim identity are not diagnostics -- they are how
        // you tell what you are about to pick up. They stay on with F1 off.

        // Crosshair
        glColor3f( 1.f, 1.f, 1.f );
        float hx = w * 0.5f, hy = h * 0.5f;
        glBegin( GL_LINES );
        glVertex2f( hx - 8, hy ); glVertex2f( hx - 2, hy );
        glVertex2f( hx + 2, hy ); glVertex2f( hx + 8, hy );
        glVertex2f( hx, hy - 8 ); glVertex2f( hx, hy - 2 );
        glVertex2f( hx, hy + 2 ); glVertex2f( hx, hy + 8 );
        glEnd();

        // Aim strike identity — color swatch + material/biome (what you seek to take).
        if ( g.aimHit )
        {
            float const sx0 = hx + 14.f, sy0 = hy - 8.f;
            float const sx1 = sx0 + 14.f, sy1 = sy0 + 14.f;
            glColor3ub( g.aimStrikeR, g.aimStrikeG, g.aimStrikeB );
            glBegin( GL_QUADS );
            glVertex2f( sx0, sy0 ); glVertex2f( sx1, sy0 );
            glVertex2f( sx1, sy1 ); glVertex2f( sx0, sy1 );
            glEnd();
            glColor3f( 0.15f, 0.15f, 0.18f );
            glBegin( GL_LINE_LOOP );
            glVertex2f( sx0, sy0 ); glVertex2f( sx1, sy0 );
            glVertex2f( sx1, sy1 ); glVertex2f( sx0, sy1 );
            glEnd();
            char strikeLine[192];
            if ( _stricmp( g.aimWireCap.c_str(), g.aimStrikeCap.c_str() ) != 0 )
            {
                std::snprintf( strikeLine, sizeof( strikeLine ),
                    "%s  %s   wire:%s",
                    g.aimStrikeCap.c_str(), g.aimBiome.c_str(), g.aimWireCap.c_str() );
            }
            else
            {
                std::snprintf( strikeLine, sizeof( strikeLine ),
                    "%s  %s", g.aimStrikeCap.c_str(), g.aimBiome.c_str() );
            }
            glColor3f( 0.98f, 0.98f, 0.92f );
            DrawHudText( sx1 + 6.f, sy0 + 2.f, strikeLine );
        }

        DrawCompass( (float)w - 56.f, (float)h - 70.f );

        // Input-ownership witness. The viewport re-entry defect was invisible from
        // the outside: capture and mouse-look looked correct while the keyboard
        // belonged to the shell. Showing all four booleans plus the focused window
        // and the live WASD bits makes the failing one nameable instead of guessed
        // at. [F9] toggles; it is diagnostic scaffolding, not chrome.
        if ( g.inputWitnessHud )
        {
            HWND const focused = GetFocus();
            char line[220];
            std::snprintf( line, sizeof( line ),
                "INPUT  viewport=%d cursor_captured=%d mouse_look=%d gameplay=%d  "
                "focus=%s(%p) self=%p  W%d A%d S%d D%d",
                g.gameplayInput ? 1 : 0, g.cursorCaptured ? 1 : 0,
                g.mouseLook ? 1 : 0, g.gameplayInput ? 1 : 0,
                ( focused == g.hwnd ) ? "SELF" : "OTHER", (void*)focused, (void*)g.hwnd,
                g.keys['W'] ? 1 : 0, g.keys['A'] ? 1 : 0,
                g.keys['S'] ? 1 : 0, g.keys['D'] ? 1 : 0 );
            bool const healthy = ( g.gameplayInput == g.mouseLook )
                              && ( !g.gameplayInput || focused == g.hwnd );
            if ( healthy ) { glColor3f( 0.45f, 0.90f, 0.55f ); }
            else { glColor3f( 1.f, 0.35f, 0.35f ); }
            DrawHudText( 16, (float)h - 24.f, line );
            glColor3f( 0.95f, 0.97f, 1.f );
        }

        if ( showHudText )
        {
        glColor3f( 0.95f, 0.97f, 1.f );
        if ( !g.walkMode )
        {
            glColor3f( 1.f, 0.85f, 0.35f );
            char flyLine[160];
            std::snprintf( flyLine, sizeof( flyLine ),
                "FREE CAMERA  speed=%.0fm/s tier=%d sprint_chain=%.1fm  [F] walk",
                g.flyCurrentSpeedMps, g.flySprintTier, g.flySprintDistanceM );
            DrawHudText( 16, 64, flyLine );
            glColor3f( 0.95f, 0.97f, 1.f );
        }
        DrawHudText( 16, 46, "LMB dig/pick  RMB place  [E] pick/drop  [B] cavity  [C] chips  [K] chip dump  scroll rolls held" );
        DrawHudText( 16, 28, "Sun+sky light materials (not painted dark sides)  tumble gold — highlight must travel" );
        DrawHudText( 16, 10, g.digestLine.c_str() );
        }
        else
        {
            DrawHudText( 16, 10, "[F1] readout" );
        }

        g.uiWinW = w;
        g.uiWinH = h;
        if ( g.journalOpen )
        {
            DrawJournal();
        }
        DrawHotbar(); // always on — pinned tabs remain when journal is closed

        glEnable( GL_DEPTH_TEST );

        SwapBuffers( g.hdc );
    }

    bool DumpFramePpm( char const* path )
    {
        GLint vp[4] = {};
        glGetIntegerv( GL_VIEWPORT, vp );
        int const w = vp[2], h = vp[3];
        if ( w <= 0 || h <= 0 ) { return false; }
        std::vector<unsigned char> rgba( (size_t)w * (size_t)h * 4u );
        glPixelStorei( GL_PACK_ALIGNMENT, 1 );
        glReadBuffer( GL_FRONT );
        glReadPixels( 0, 0, w, h, GL_RGBA, GL_UNSIGNED_BYTE, rgba.data() );
        FILE* f = nullptr;
        if ( fopen_s( &f, path, "wb" ) != 0 || !f ) { return false; }
        std::fprintf( f, "P6\n%d %d\n255\n", w, h );
        for ( int y = h - 1; y >= 0; --y )
        {
            for ( int x = 0; x < w; ++x )
            {
                size_t const i = ( (size_t)y * (size_t)w + (size_t)x ) * 4u;
                unsigned char rgb[3] = { rgba[i], rgba[i + 1], rgba[i + 2] };
                std::fwrite( rgb, 1, 3, f );
            }
        }
        std::fclose( f );
        return true;
    }

    bool DumpDepthPpm( char const* path, float nearZ, float farZ )
    {
        // Encode linear eye-space depth at 0.1 mm precision in R:G. B is an
        // explicit validity channel, so the comparison tool never mistakes the
        // cleared far plane for facial relief. This pass is read from the exact
        // skin-only depth buffer before presentation; it is not inferred from
        // lighting or the beauty colour.
        GLint vp[4] = {};
        glGetIntegerv( GL_VIEWPORT, vp );
        int const w = vp[2], h = vp[3];
        if ( w <= 0 || h <= 0 || nearZ <= 0.f || farZ <= nearZ ) { return false; }
        std::vector<float> depth( (size_t)w * (size_t)h, 1.f );
        glPixelStorei( GL_PACK_ALIGNMENT, 1 );
        glReadPixels( 0, 0, w, h, GL_DEPTH_COMPONENT, GL_FLOAT, depth.data() );
        FILE* f = nullptr;
        if ( fopen_s( &f, path, "wb" ) != 0 || !f ) { return false; }
        std::fprintf( f, "P6\n%d %d\n255\n", w, h );
        for ( int y = h - 1; y >= 0; --y )
        {
            for ( int x = 0; x < w; ++x )
            {
                float const d = depth[(size_t)y * (size_t)w + (size_t)x];
                bool const valid = d < 0.999999f;
                unsigned int code = 0u;
                if ( valid )
                {
                    float const ndc = d * 2.f - 1.f;
                    float const linear = ( 2.f * nearZ * farZ )
                        / ( farZ + nearZ - ndc * ( farZ - nearZ ) );
                    code = (unsigned int)std::clamp( std::lround( linear * 10000.f ), 0l, 65535l );
                }
                unsigned char rgb[3] = { (unsigned char)( code >> 8u ),
                    (unsigned char)( code & 255u ), (unsigned char)( valid ? 255 : 0 ) };
                std::fwrite( rgb, 1, 3, f );
            }
        }
        std::fclose( f );
        return true;
    }

    int CountLowerPpmSkyPixels(char const* path)
    {
        FILE* f=nullptr;if(fopen_s(&f,path,"rb")!=0||!f)return INT_MAX;
        char magic[3]={};int w=0,h=0,maxv=0;
        if(std::fscanf(f,"%2s %d %d %d",magic,&w,&h,&maxv)!=4
          ||std::strcmp(magic,"P6")!=0||w<=0||h<=0||maxv!=255)
        {std::fclose(f);return INT_MAX;}
        (void)std::fgetc(f);
        std::vector<unsigned char> rgb((size_t)w*(size_t)h*3u);
        bool const read=std::fread(rgb.data(),1,rgb.size(),f)==rgb.size();
        std::fclose(f);if(!read)return INT_MAX;
        int sky=0;
        // DumpFramePpm is top-down. The selected downward continuity view must
        // contain no sky-clear pixels in the lower 45 percent.
        for(int y=h*55/100;y<h;++y)for(int x=0;x<w;++x)
        {
            size_t const i=((size_t)y*(size_t)w+(size_t)x)*3u;
            int const r=rgb[i],green=rgb[i+1],b=rgb[i+2];
            if(std::abs(r-114)<=2&&std::abs(green-158)<=2&&std::abs(b-224)<=2)++sky;
        }
        return sky;
    }

    int CountLowerPpmDarkPixels(char const* path,int* sampled=nullptr)
    {
        if(sampled)*sampled=0;FILE* f=nullptr;if(fopen_s(&f,path,"rb")!=0||!f)return INT_MAX;
        char magic[3]={};int w=0,h=0,maxv=0;
        if(std::fscanf(f,"%2s %d %d %d",magic,&w,&h,&maxv)!=4
          ||std::strcmp(magic,"P6")!=0||w<=0||h<=0||maxv!=255)
        {std::fclose(f);return INT_MAX;}
        (void)std::fgetc(f);std::vector<unsigned char> rgb((size_t)w*(size_t)h*3u);
        bool const read=std::fread(rgb.data(),1,rgb.size(),f)==rgb.size();std::fclose(f);
        if(!read)return INT_MAX;int dark=0,total=0;
        for(int y=h*55/100;y<h;++y)for(int x=0;x<w;++x)
        {size_t const i=((size_t)y*(size_t)w+(size_t)x)*3u;++total;
            if(rgb[i]<8&&rgb[i+1]<8&&rgb[i+2]<8)++dark;}
        if(sampled)*sampled=total;return dark;
    }

    bool CaptureStage0GeologyXraySnapshot()
    {
        Stage0InspectorFrame inspector{};
        if(!Stage0GeologyInspectorFrame(inspector)){return false;}
        float tx,ty,tz;Stage0InspectorPoint(inspector,g.stage0GeologyInspectorDepthM,
            0.f,0.f,tx,ty,tz);
        auto const terminal=CausalGeologyAt(g.stage0PlayView,tx,ty,tz);
        if(!terminal.found){return false;}
        glFinish();
        GLint vp[4]={};glGetIntegerv(GL_VIEWPORT,vp);
        int depositPixels=0;
        if(vp[2]>0&&vp[3]>0)
        {
            std::vector<unsigned char> rgba((size_t)vp[2]*(size_t)vp[3]*4u);
            glPixelStorei(GL_PACK_ALIGNMENT,1);glReadBuffer(GL_FRONT);
            glReadPixels(0,0,vp[2],vp[3],GL_RGBA,GL_UNSIGNED_BYTE,rgba.data());
            for(int y=vp[3]/4;y<vp[3]*3/4;++y)for(int x=vp[2]/4;x<vp[2]*3/4;++x)
            {
                size_t const i=((size_t)y*(size_t)vp[2]+(size_t)x)*4u;
                int const r=rgba[i],green=rgba[i+1],b=rgba[i+2];
                if(r>180&&green>160&&b<165&&r>b+35&&green>b+25)++depositPixels;
            }
        }
        bool const cutC=IsCutCOccupancyView(g.stage0PlayView);
        bool const breach=IsSurfaceBreachView(g.stage0PlayView);
        bool const exact=IsExactLocalMaterializationView(g.stage0PlayView);
        bool const pick=IsSinglePickProofView(g.stage0PlayView);
        bool const terminalIsCertifiedDeposit=terminal.material=="quartz"
          &&(!(breach||exact||pick)||(g.causalBreachRuntime&&g.causalBreachRuntime->IsTarget(terminal)));
        char const* imagePath=pick?"Docs\\provenance_stage14_single_pick_after_xray.ppm"
            :(exact?"Docs\\provenance_stage13_exact_local_materialization_xray.ppm"
            :(breach?"Docs\\provenance_stage12_surface_breach_xray.ppm"
            :(cutC?"Docs\\provenance_cut_c_player_xray.ppm"
            :"Docs\\provenance_geology_xray_snapshot.ppm")));
        char const* receiptPath=pick?"Docs\\provenance_stage14_single_pick_after_xray.txt"
            :(exact?"Docs\\provenance_stage13_exact_local_materialization_xray.txt"
            :(breach?"Docs\\provenance_stage12_surface_breach_xray.txt"
            :(cutC?"Docs\\provenance_cut_c_player_xray.txt"
            :"Docs\\provenance_geology_xray_snapshot.txt")));
        bool const image=DumpFramePpm(imagePath);
        FILE* f=nullptr;
        bool const opened=fopen_s(&f,receiptPath,"w")==0&&f;
        if(opened)
        {
            std::fprintf(f,"PROVENANCE_GEOLOGY_XRAY_SNAPSHOT\nimage=%s\n"
                "stage=%s\ncontact=%.6f,%.6f,%.6f\ndepth_m=%.6f\nwidth_m=%.6f\n"
                "terminal=%.6f,%.6f,%.6f\nmaterial=%s\nfeature_id=%s\nformation=%s\n"
                "deposit_visible=%d\ndeposit_pixels=%d\nevent_count=%zu\nchronology_count=%zu\n"
                "presentation_only=1\n",
                image?(pick?"Docs/provenance_stage14_single_pick_after_xray.ppm"
                    :(exact?"Docs/provenance_stage13_exact_local_materialization_xray.ppm"
                    :(breach?"Docs/provenance_stage12_surface_breach_xray.ppm"
                    :(cutC?"Docs/provenance_cut_c_player_xray.ppm"
                    :"Docs/provenance_geology_xray_snapshot.ppm")))):"WRITE_FAILED",
                Stage0PlayViewName(g.stage0PlayView),inspector.px,inspector.py,inspector.pz,
                g.stage0GeologyInspectorDepthM,g.stage0GeologyInspectorWidthM,tx,ty,tz,
                terminal.material.c_str(),CausalWorldGeology::Hex64(terminal.featureId).c_str(),
                terminal.formationId.c_str(),terminalIsCertifiedDeposit&&depositPixels>=128?1:0,
                depositPixels,
                terminal.eventIds.size(),terminal.chronology.size());
            std::fclose(f);
        }
        g.stage0GeologySnapshotSucceeded=image&&opened;
        g.stage0GeologySnapshotDepositPixels=depositPixels;
        g.stage0GeologySnapshotDepositVisible=terminalIsCertifiedDeposit&&depositPixels>=128;
        return g.stage0GeologySnapshotSucceeded;
    }

    bool CaptureStage11FaultXraySnapshot()
    {
        if(!IsFaultDisplacementView(g.stage0PlayView)||!g.causalFaultRuntime)return false;
        Stage0InspectorFrame inspector{};if(!Stage0GeologyInspectorFrame(inspector))return false;
        float tx,ty,tz;Stage0InspectorPoint(inspector,g.stage0GeologyInspectorDepthM,
            0.f,0.f,tx,ty,tz);
        auto const terminal=g.causalFaultRuntime->Query(true,tx,ty,tz);
        uint64_t const quartzId=0xda10b0d1e5f01001ull;
        int footwallQuartz=0,hangingQuartz=0;
        bool selectedQuartz=false,selectedShifted=false;
        float selectedX=0.f,selectedY=0.f,selectedZ=0.f;
        std::array<double,3> selectedSource{};
        CausalWorldGeology::GeoSample selectedPost{},selectedPre{};
        float const half=g.stage0GeologyInspectorWidthM*.5f;
        for(float r=-half;r<=half+1e-4f;r+=.125f)
        for(float u=-half;u<=half+1e-4f;u+=.125f)
        {
            float x,y,z;Stage0InspectorPoint(inspector,g.stage0GeologyInspectorDepthM,
                r,u,x,y,z);
            auto const sample=g.causalFaultRuntime->Query(true,x,y,z);
            if(sample.found&&sample.featureId==quartzId)
            {
                if(g.causalFaultRuntime->SignedDistance(x,y,z)>=0.0)
                {
                    ++hangingQuartz;
                    if(!selectedQuartz)
                    {
                        selectedPost=sample;selectedX=x;selectedY=y;selectedZ=z;
                        selectedSource=g.causalFaultRuntime->SourcePoint(
                            true,x,y,z,&selectedShifted);
                        selectedPre=g.causalFaultRuntime->Stage10().Query(true,
                            selectedSource[0],selectedSource[1],selectedSource[2]);
                        selectedQuartz=true;
                    }
                }
                else ++footwallQuartz;
            }
        }
        bool const sameIdentity=selectedQuartz&&selectedShifted
          &&selectedPost.found&&selectedPre.found
          &&selectedPost.material=="quartz"&&selectedPost.featureId==quartzId
          &&selectedPost.featureId==selectedPre.featureId
          &&!selectedPost.eventIds.empty()
          &&selectedPost.eventIds.back()==g.causalFaultRuntime->GetProgram().faultEventId;
        glFinish();bool const image=DumpFramePpm(
            "Docs\\provenance_stage11_fault_identity_xray.ppm");
        FILE* f=nullptr;bool const opened=fopen_s(&f,
            "Docs\\provenance_stage11_fault_identity_xray.txt","wb")==0&&f;
        if(opened)
        {
            std::fprintf(f,"PROVENANCE_STAGE11_FAULT_IDENTITY_XRAY %s\n"
                "image=Docs/provenance_stage11_fault_identity_xray.ppm\n"
                "mode=IDENTITY\ncontact=%.6f,%.6f,%.6f\nterminal=%.6f,%.6f,%.6f\n"
                "selected_post=%.6f,%.6f,%.6f\nsource=%.6f,%.6f,%.6f\n"
                "feature_id=%s\nfault_event_id=%s\n"
                "footwall_quartz_samples=%d\nhanging_wall_quartz_samples=%d\n"
                "same_identity=%d\npresentation_only=1\n",
                image&&sameIdentity&&footwallQuartz>0&&hangingQuartz>0?"PASS":"FAIL",
                inspector.px,inspector.py,inspector.pz,tx,ty,tz,
                selectedX,selectedY,selectedZ,
                selectedSource[0],selectedSource[1],selectedSource[2],
                CausalWorldGeology::Hex64(selectedPost.featureId).c_str(),
                CausalWorldGeology::Hex64(
                    g.causalFaultRuntime->GetProgram().faultEventId).c_str(),
                footwallQuartz,hangingQuartz,sameIdentity?1:0);
            std::fclose(f);
        }
        return image&&opened&&sameIdentity&&footwallQuartz>0&&hangingQuartz>0;
    }

    void WriteCertPixelReport( char const* ppmPath, char const* reportPath )
    {
        constexpr int kVoidR = 114, kVoidG = 158, kVoidB = 224;
        constexpr int kGrassR = 93, kGrassG = 133, kGrassB = 68;
        constexpr int kLimeR = 193, kLimeG = 189, kLimeB = 174;
        constexpr int kMicaR = 126, kMicaG = 123, kMicaB = 107;
        // Legacy backdrop ground quad (pre-voidfix) — exact RGB(178,204,140); not grass.
        constexpr int kBackR = 178, kBackG = 204, kBackB = 140;
        GLint vp[4] = {};
        glGetIntegerv( GL_VIEWPORT, vp );
        int const w = vp[2], h = vp[3];
        if ( w <= 8 || h <= 8 ) { return; }
        std::vector<unsigned char> rgba( (size_t)w * (size_t)h * 4u );
        glPixelStorei( GL_PACK_ALIGNMENT, 1 );
        glReadPixels( 0, 0, w, h, GL_RGBA, GL_UNSIGNED_BYTE, rgba.data() );
        int x0 = w * 2 / 5, x1 = w * 3 / 5, y0 = h * 2 / 5, y1 = h * 3 / 5;
        long long n = 0, sky = 0, grassN = 0, chalk = 0, dark = 0, back = 0, other = 0;
        auto d2 = []( int r, int gc, int b, int rr, int gg, int bb ) {
            long long dr = r - rr, dg = gc - gg, db = b - bb;
            return dr * dr + dg * dg + db * db;
        };
        for ( int y = y0; y < y1; ++y )
        {
            for ( int x = x0; x < x1; ++x )
            {
                size_t const i = ( (size_t)y * (size_t)w + (size_t)x ) * 4u;
                int r = rgba[i], gc = rgba[i + 1], b = rgba[i + 2];
                ++n;
                if ( r + gc + b < 90 ) { ++dark; continue; }
                if ( d2( r, gc, b, kBackR, kBackG, kBackB ) <= 64 ) { ++back; continue; }
                long long dv = d2( r, gc, b, kVoidR, kVoidG, kVoidB );
                long long dg = d2( r, gc, b, kGrassR, kGrassG, kGrassB );
                long long dc = d2( r, gc, b, kLimeR, kLimeG, kLimeB );
                long long dm = d2( r, gc, b, kMicaR, kMicaG, kMicaB );
                if ( b > gc && b > r && b > 150 && dv <= dg && dv <= dc ) { ++sky; continue; }
                if ( dg <= dv && dg <= dc && dg <= dm && gc > r + 20 && gc > b + 20 ) { ++grassN; continue; }
                if ( dc <= dv && dc <= dg && ( dc <= dm || r + gc + b > 480 ) ) { ++chalk; continue; }
                ++other;
            }
        }
        FILE* f = nullptr;
        if ( fopen_s( &f, reportPath, "w" ) != 0 || !f ) { return; }
        std::fprintf( f,
            "ppm=%s\nviewport=%dx%d\ncenter_samples=%lld\n"
            "refs: void_clear=RGB(%d,%d,%d) grass_mid=RGB(%d,%d,%d) limestone_mid=RGB(%d,%d,%d) mica_mid=RGB(%d,%d,%d) legacy_backdrop=RGB(%d,%d,%d)\n"
            "class_sky_void_pct=%.2f\nclass_legacy_backdrop_void_pct=%.2f\nclass_grass_pct=%.2f\nclass_chalk_stone_pct=%.2f\nclass_shadow_dark_pct=%.2f\nclass_other_pct=%.2f\n"
            "digest=%s\naim=%s/%s\ncavity_tris=%d\n"
            "note=mesh gap void=sky clear (or legacy lime backdrop); grass mid is olive CapColor — never RGB(178,204,140)\n",
            ppmPath, w, h, n,
            kVoidR, kVoidG, kVoidB, kGrassR, kGrassG, kGrassB, kLimeR, kLimeG, kLimeB, kMicaR, kMicaG, kMicaB,
            kBackR, kBackG, kBackB,
            n ? ( 100.0 * sky / n ) : 0.0,
            n ? ( 100.0 * back / n ) : 0.0,
            n ? ( 100.0 * grassN / n ) : 0.0,
            n ? ( 100.0 * chalk / n ) : 0.0,
            n ? ( 100.0 * dark / n ) : 0.0,
            n ? ( 100.0 * other / n ) : 0.0,
            g.digestLine.c_str(),
            g.aimStrikeCap.c_str(), g.aimWireCap.c_str(),
            g.cavityTrisTotal );
        std::fclose( f );
    }

